422:   public static Either<ProblemDetail, List<DocumentCreateRequest>> toDocumentCreateRequestBatch(
423:       final List<Part> parts, final String storeId, final ObjectMapper objectMapper) {
424:     final Map<Part, DocumentMetadata> metadataMap =
425:         parts.stream()
426:             .collect(
427:                 Collectors.toMap(
428:                     part -> part,
429:                     part ->
430:                         Optional.ofNullable(part.getHeader("X-Document-Metadata"))
431:                             .map(
432:                                 header -> {
433:                                   try {
434:                                     return objectMapper.readValue(header, DocumentMetadata.class);
435:                                   } catch (final IOException e) {
436:                                     throw new RuntimeException(e);
437:                                   }
438:                                 })
439:                             .orElse(new DocumentMetadata())));
440: 
441:     final ProblemDetail validationErrors =
442:         metadataMap.values().stream()
443:             .map(DocumentValidator::validateDocumentMetadata)
444:             .filter(Optional::isPresent)
445:             .map(Optional::get)
446:             .reduce( // combine violations from each problem detail
447:                 ProblemDetail.forStatus(HttpStatus.BAD_REQUEST),
448:                 (acc, detail) -> {
449:                   acc.setDetail(acc.getDetail() + ". " + detail.getDetail());
450:                   return acc;
451:                 });
452: 
453:     if (validationErrors.getDetail() != null) {
454:       return Either.left(validationErrors);
455:     }
456: 
457:     final var requests = new HashMap<Part, DocumentCreateRequest>();
458:     for (final var part : parts) {
459:       final var metadata = metadataMap.get(part);
460:       final InputStream inputStream;
461:       try {
462:         inputStream = part.getInputStream();
463:       } catch (final IOException e) {
464:         return Either.left(createInternalErrorProblemDetail(e, "Failed to read document content"));
465:       }
466:       requests.put(
467:           part,
468:           new DocumentCreateRequest(
469:               null, storeId, inputStream, toInternalDocumentMetadata(metadata, part)));
470:     }
471:     return Either.right(List.copyOf(requests.values()));
472:   }
