690:   private static DocumentMetadataModel toInternalDocumentMetadata(
691:       final DocumentMetadata metadata, final Part file) {
692: 
693:     if (metadata == null) {
694:       return new DocumentMetadataModel(
695:           file.getContentType(),
696:           file.getSubmittedFileName(),
697:           null,
698:           file.getSize(),
699:           null,
700:           null,
701:           Map.of());
702:     }
703:     final OffsetDateTime expiresAt;
704:     if (metadata.getExpiresAt() == null || metadata.getExpiresAt().isBlank()) {
705:       expiresAt = null;
706:     } else {
707:       expiresAt = OffsetDateTime.parse(metadata.getExpiresAt());
708:     }
709:     final var fileName =
710:         Optional.ofNullable(metadata.getFileName()).orElse(file.getSubmittedFileName());
711:     final var contentType =
712:         Optional.ofNullable(metadata.getContentType()).orElse(file.getContentType());
713: 
714:     return new DocumentMetadataModel(
715:         contentType,
716:         fileName,
717:         expiresAt,
718:         file.getSize(),
719:         metadata.getProcessDefinitionId(),
720:         KeyUtil.keyToLong(metadata.getProcessInstanceKey()),
721:         metadata.getCustomProperties());
722:   }
