83:                 builder.getElasticsearchDockerImageVersion())
84:             .withLogConsumer(createContainerLogger(builder.getElasticsearchLoggerName()))
85:             .withNetwork(network)
86:             .withNetworkAliases(NETWORK_ALIAS_ELASTICSEARCH)
87:             .withEnv(ContainerRuntimeEnvs.ELASTICSEARCH_ENV_XPACK_SECURITY_ENABLED, "false")
88:             .withEnv(builder.getElasticsearchEnvVars());
