103:             .withNetwork(network)
104:             .withNetworkAliases(NETWORK_ALIAS_CAMUNDA)
105:             .withEnv(builder.getCamundaEnvVars());
106: 
107:     builder.getCamundaExposedPorts().forEach(container::addExposedPort);
108: 
109:     return container;
110:   }
