123:   public static HttpWaitStrategy newDefaultBrokerReadyCheck() {
124:     return new HttpWaitStrategy()
125:         .forPath(READY_ENDPOINT)
126:         .forPort(ContainerRuntimePorts.CAMUNDA_MONITORING_API)
127:         .forStatusCodeMatching(status -> status >= 200 && status < 300)
128:         .withReadTimeout(DEFAULT_READINESS_TIMEOUT);
129:   }
