131:   public static HttpWaitStrategy newDefaultTopologyReadyCheck() {
132:     return new HttpWaitStrategy()
133:         .forPath(TOPOLOGY_ENDPOINT)
134:         .forPort(ContainerRuntimePorts.CAMUNDA_REST_API)
135:         .forStatusCodeMatching(status -> status >= 200 && status < 300)
136:         .forResponsePredicate(CamundaContainer::isPartitionReady)
137:         .withReadTimeout(DEFAULT_READINESS_TIMEOUT);
