49: /**
50:  * A JUnit extension that provides the runtime for process tests.
51:  *
52:  * <p>The container runtime starts before any tests have run.
53:  *
54:  * <p>Before each test method:
55:  *
56:  * <ul>
57:  *   <li>Inject a {@link CamundaClient} to a field in the test class
58:  *   <li>Inject a {@link CamundaProcessTestContext} to a field in the test class
59:  * </ul>
60:  *
61:  * <p>After each test method:
62:  *
63:  * <ul>
64:  *   <li>Close created {@link CamundaClient}s
65:  *   <li>Purge the runtime (i.e. delete all data)
66:  * </ul>
67:  *
68:  * <p>The container runtime is closed once all tests have run.
69:  */
70: public class CamundaProcessTestExtension
71:     implements BeforeEachCallback, BeforeAllCallback, AfterEachCallback, AfterAllCallback {
72: 
73:   /** The JUnit extension namespace to store the runtime and context. */
74:   public static final Namespace NAMESPACE = Namespace.create(CamundaProcessTestExtension.class);
75: 
76:   /** The JUnit extension store key of the runtime. */
77:   public static final String STORE_KEY_RUNTIME = "camunda-process-test-runtime";
78: 
79:   /** The JUnit extension store key of the context. */
80:   public static final String STORE_KEY_CONTEXT = "camunda-process-test-context";
81: 
82:   private static final Logger LOG = LoggerFactory.getLogger(CamundaProcessTestExtension.class);
83: 
84:   private final List<AutoCloseable> createdClients = new ArrayList<>();
85: 
86:   private final CamundaContainerRuntimeBuilder containerRuntimeBuilder;
87:   private final CamundaProcessTestResultPrinter processTestResultPrinter;
88: 
89:   private CamundaContainerRuntime containerRuntime;
90:   private CamundaProcessTestResultCollector processTestResultCollector;
91: 
92:   private CamundaManagementClient camundaManagementClient;
93:   private CamundaProcessTestContext camundaProcessTestContext;
94: 
95:   CamundaProcessTestExtension(
96:       final CamundaContainerRuntimeBuilder containerRuntimeBuilder,
97:       final Consumer<String> testResultPrintStream) {
98:     this.containerRuntimeBuilder = containerRuntimeBuilder;
99:     processTestResultPrinter = new CamundaProcessTestResultPrinter(testResultPrintStream);
100:   }
101: 
102:   /**
103:    * Creates a new instance of the extension. Can be used to configure the runtime.
104:    *
105:    * <p>Example usage:
106:    *
107:    * <pre>
108:    * public class MyProcessTest {
109:    *
110:    *   &#064;RegisterExtension
111:    *   public CamundaProcessTestExtension extension =
112:    *       new CamundaProcessTestExtension().withCamundaVersion("8.6.0");
113:    *
114:    * }
115:    * </pre>
116:    */
117:   public CamundaProcessTestExtension() {
118:     this(CamundaContainerRuntime.newBuilder(), System.err::println);
119:   }
120: 
121:   @Override
122:   public void beforeAll(final ExtensionContext context) {
123:     // create runtime
124:     containerRuntime = containerRuntimeBuilder.build();
125:     containerRuntime.start();
126: 
127:     camundaManagementClient =
128:         new CamundaManagementClient(
129:             containerRuntime.getCamundaContainer().getMonitoringApiAddress(),
130:             containerRuntime.getCamundaContainer().getRestApiAddress());
131: 
132:     camundaProcessTestContext =
133:         new CamundaProcessTestContextImpl(
134:             containerRuntime.getCamundaContainer(),
135:             containerRuntime.getConnectorsContainer(),
136:             createdClients::add,
137:             camundaManagementClient);
138: 
139:     // put in store
140:     final Store store = context.getStore(NAMESPACE);
141:     store.put(STORE_KEY_RUNTIME, containerRuntime);
142:     store.put(STORE_KEY_CONTEXT, camundaProcessTestContext);
143:   }
144: 
145:   @Override
146:   public void beforeEach(final ExtensionContext context) throws Exception {
147:     if (containerRuntime == null) {
148:       throw new IllegalStateException(
149:           "The CamundaProcessTestExtension failed to start because the runtime is not created. "
150:               + "Make sure that you registering the extension on a static field.");
151:     }
152: 
153:     // inject fields
154:     try {
155:       injectField(context, CamundaClient.class, camundaProcessTestContext::createClient);
156:       injectField(context, ZeebeClient.class, camundaProcessTestContext::createZeebeClient);
157:       injectField(context, CamundaProcessTestContext.class, () -> camundaProcessTestContext);
158:     } catch (final Exception e) {
159:       closeCreatedClients();
160:       containerRuntime.close();
161:       throw e;
162:     }
163: 
164:     // initialize assertions
165:     final CamundaDataSource dataSource =
166:         new CamundaDataSource(camundaProcessTestContext.createClient());
167:     CamundaAssert.initialize(dataSource);
168: 
169:     // initialize result collector
170:     processTestResultCollector = new CamundaProcessTestResultCollector(dataSource);
171:   }
172: 
173:   private <T> void injectField(
174:       final ExtensionContext context,
175:       final Class<T> injectionType,
176:       final Supplier<T> injectionValue) {
177:     context
178:         .getRequiredTestInstances()
179:         .getAllInstances()
180:         .forEach(instance -> injectField(instance, injectionType, injectionValue));
181:   }
182: 
183:   private <T> void injectField(
184:       final Object testInstance, final Class<T> injectionType, final Supplier<T> injectionValue) {
185:     ReflectionUtils.findFields(
186:             testInstance.getClass(),
187:             field -> isNotStatic(field) && field.getType().isAssignableFrom(injectionType),
188:             ReflectionUtils.HierarchyTraversalMode.TOP_DOWN)
189:         .forEach(
190:             field -> {
191:               try {
192:                 field.setAccessible(true);
193:                 field.set(testInstance, injectionValue.get());
194:               } catch (final Throwable t) {
195:                 ExceptionUtils.throwAsUncheckedException(t);
196:               }
197:             });
198:   }
199: 
200:   private static boolean isNotStatic(final Field field) {
201:     return !Modifier.isStatic(field.getModifiers());
202:   }
203: 
204:   @Override
205:   public void afterEach(final ExtensionContext extensionContext) {
206:     if (containerRuntime == null) {
207:       // Skip if the runtime is not created.
208:       return;
209:     }
210: 
211:     if (isTestFailed(extensionContext)) {
212:       printTestResults();
213:     }
214:     CamundaAssert.reset();
215:     closeCreatedClients();
216:     // final step: delete data
217:     deleteRuntimeData();
218:   }
219: 
220:   private void printTestResults() {
221:     try {
222:       // collect test results
223:       final ProcessTestResult testResult = processTestResultCollector.collect();
224:       // print test results
225:       processTestResultPrinter.print(testResult);
226:     } catch (final Throwable t) {
227:       LOG.warn("Failed to collect test results, skipping.", t);
228:     }
229:   }
230: 
231:   private void deleteRuntimeData() {
232:     try {
233:       LOG.debug("Deleting the runtime data");
234:       final Instant startTime = Instant.now();
235: 
236:       camundaManagementClient.purgeCluster();
237:       final Instant endTime = Instant.now();
238:       final Duration duration = Duration.between(startTime, endTime);
239:       LOG.debug("Runtime data deleted in {}", duration);
240: 
241:     } catch (final Throwable t) {
242:       LOG.warn(
243:           "Failed to delete the runtime data, skipping. Check the runtime for details. "
244:               + "Note that a dirty runtime may cause failures in other test cases.",
245:           t);
246:     }
247:   }
248: 
249:   @Override
250:   public void afterAll(final ExtensionContext context) throws Exception {
251:     if (containerRuntime == null) {
252:       // Skip if the runtime is not created.
253:       return;
254:     }
255:     containerRuntime.close();
256:   }
257: 
258:   private static boolean isTestFailed(final ExtensionContext extensionContext) {
259:     return extensionContext.getExecutionException().isPresent();
260:   }
