281:    * @return the extension builder
282:    */
283:   public CamundaProcessTestExtension withCamundaDockerImageName(final String dockerImageName) {
284:     containerRuntimeBuilder.withCamundaDockerImageName(dockerImageName);
285:     return this;
286:   }
287: 
288:   /**
289:    * Add environment variables to the Camunda runtime.
290:    *
291:    * @param envVars environment variables to add
292:    * @return the extension builder
293:    */
294:   public CamundaProcessTestExtension withCamundaEnv(final Map<String, String> envVars) {
295:     containerRuntimeBuilder.withCamundaEnv(envVars);
296:     return this;
297:   }
298: 
299:   /**
300:    * Add an environment variable to the Camunda runtime.
301:    *
302:    * @param name the variable name
303:    * @param value the variable value
304:    * @return the extension builder
305:    */
306:   public CamundaProcessTestExtension withCamundaEnv(final String name, final String value) {
307:     containerRuntimeBuilder.withCamundaEnv(name, value);
308:     return this;
309:   }
310: 
311:   /**
312:    * Add an exposed port to the Camunda runtime.
313:    *
314:    * @param port the port to add
315:    * @return the extension builder
316:    */
317:   public CamundaProcessTestExtension withCamundaExposedPort(final int port) {
318:     containerRuntimeBuilder.withCamundaExposedPort(port);
319:     return this;
320:   }
321: 
322:   /**
323:    * Enable or disable the Connectors. By default, the Connectors are disabled.
324:    *
325:    * @param enabled set {@code true} to enable the Connectors
326:    * @return the extension builder
327:    */
328:   public CamundaProcessTestExtension withConnectorsEnabled(final boolean enabled) {
329:     containerRuntimeBuilder.withConnectorsEnabled(enabled);
330:     return this;
331:   }
332: 
333:   /**
334:    * Configure the Connectors Docker image name of the runtime.
335:    *
336:    * @param dockerImageName the Docker image name to use
337:    * @return the extension builder
338:    */
339:   public CamundaProcessTestExtension withConnectorsDockerImageName(final String dockerImageName) {
340:     containerRuntimeBuilder.withConnectorsDockerImageName(dockerImageName);
341:     return this;
342:   }
343: 
344:   /**
345:    * Configure the Connectors Docker image version of the runtime.
346:    *
347:    * @param dockerImageVersion the version to use
