349:    */
350:   public CamundaProcessTestExtension withConnectorsDockerImageVersion(
351:       final String dockerImageVersion) {
352:     containerRuntimeBuilder.withConnectorsDockerImageVersion(dockerImageVersion);
353:     return this;
354:   }
355: 
356:   /**
357:    * Add environment variables to the Connectors runtime.
358:    *
359:    * @param envVars environment variables to add
360:    * @return the extension builder
361:    */
362:   public CamundaProcessTestExtension withConnectorsEnv(final Map<String, String> envVars) {
363:     containerRuntimeBuilder.withConnectorsEnv(envVars);
364:     return this;
365:   }
366: 
367:   /**
368:    * Add an environment variable to the Connectors runtime.
