370:    * @param name the variable name
371:    * @param value the variable value
372:    * @return the extension builder
373:    */
374:   public CamundaProcessTestExtension withConnectorsEnv(final String name, final String value) {
375:     containerRuntimeBuilder.withConnectorsEnv(name, value);
376:     return this;
