136:             containerRuntime.getCamundaContainer().getRestApiAddress());
137: 
138:     camundaProcessTestContext =
139:         new CamundaProcessTestContextImpl(
140:             containerRuntime.getCamundaContainer(),
141:             containerRuntime.getConnectorsContainer(),
142:             createdClients::add,
143:             camundaManagementClient);
144: 
145:     // put in store
146:     final Store store = context.getStore(NAMESPACE);
147:     store.put(STORE_KEY_RUNTIME, containerRuntime);
148:     store.put(STORE_KEY_CONTEXT, camundaProcessTestContext);
149:   }
150: 
151:   @Override
152:   public void beforeEach(final ExtensionContext context) throws Exception {
153:     if (containerRuntime == null) {
154:       throw new IllegalStateException(
155:           "The CamundaProcessTestExtension failed to start because the runtime is not created. "
156:               + "Make sure that you registering the extension on a static field.");
157:     }
158: 
159:     // inject fields
160:     try {
161:       injectField(context, CamundaClient.class, camundaProcessTestContext::createClient);
162:       injectField(context, ZeebeClient.class, camundaProcessTestContext::createZeebeClient);
163:       injectField(context, CamundaProcessTestContext.class, () -> camundaProcessTestContext);
164:     } catch (final Exception e) {
165:       closeCreatedClients();
166:       containerRuntime.close();
167:       throw e;
168:     }
169: 
170:     // initialize assertions
171:     final CamundaDataSource dataSource =
172:         new CamundaDataSource(camundaProcessTestContext.createClient());
173:     CamundaAssert.initialize(dataSource);
174: 
175:     // initialize result collector
176:     processTestResultCollector = new CamundaProcessTestResultCollector(dataSource);
177:   }
