179:   private <T> void injectField(
180:       final ExtensionContext context,
181:       final Class<T> injectionType,
182:       final Supplier<T> injectionValue) {
183:     context
184:         .getRequiredTestInstances()
185:         .getAllInstances()
186:         .forEach(instance -> injectField(instance, injectionType, injectionValue));
187:   }
