189:   private <T> void injectField(
190:       final Object testInstance, final Class<T> injectionType, final Supplier<T> injectionValue) {
191:     ReflectionUtils.findFields(
192:             testInstance.getClass(),
193:             field -> isNotStatic(field) && field.getType().isAssignableFrom(injectionType),
194:             ReflectionUtils.HierarchyTraversalMode.TOP_DOWN)
195:         .forEach(
196:             field -> {
197:               try {
198:                 field.setAccessible(true);
199:                 field.set(testInstance, injectionValue.get());
200:               } catch (final Throwable t) {
201:                 ExceptionUtils.throwAsUncheckedException(t);
202:               }
