240:       final Instant startTime = Instant.now();
241: 
242:       camundaManagementClient.purgeCluster();
243:       final Instant endTime = Instant.now();
244:       final Duration duration = Duration.between(startTime, endTime);
245:       LOG.debug("Runtime data deleted in {}", duration);
246: 
247:     } catch (final Throwable t) {
