269:   /**
270:    * Command to migrate a process instance to a different process definition.
271:    *
272:    * <p>The migration command contains a migration plan. Migration plan contains
273:    * targetProcessDefinitionKey to indicate which process definition to use for the migration.
274:    * Mapping instructions for the migration describe how to map elements from the source process
275:    * definition to the target process definition.
276:    *
277:    * <p>For example, let's consider we want to migrate process instance with key {@code 1}, target
278:    * process definition key {@code 2}, a source process definition with a service task with id
279:    * {@code "task1"} and the target process definition with a service task with id {@code "task2"}.
280:    * The migration command could be:
281:    *
282:    * <pre>{@code
283:    * {
284:    *  "processInstanceKey": 1,
285:    *  "migrationPlan": {
286:    *   "targetProcessDefinitionKey": 2,
287:    *   "mappingInstructions": [
288:    *    {
289:    *     "sourceElementId": "task1",
290:    *     "targetElementId": "task2"
291:    *    }
292:    *   ]
293:    *  }
294:    * }
295:    * }</pre>
296:    *
297:    * <pre>
298:    *
299:    * camundaClient
300:    *  .newMigrateProcessInstanceCommand(1L)
301:    *  .migrationPlan(2L)
302:    *  .addMappingInstruction("element1", "element2")
303:    *  .addMappingInstruction("element3", "element4")
304:    *  .send();
305:    * </pre>
306:    *
307:    * <pre>
308:    * final MigrationPlan migrationPlan =
309:    *         MigrationPlan.newBuilder()
310:    *             .withTargetProcessDefinitionKey(2L)
311:    *             .addMappingInstruction("element1", "element2")
312:    *             .addMappingInstruction("element3", "element4")
313:    *             .build();
314:    * camundaClient
315:    *  .newMigrateProcessInstanceCommand(1L)
316:    *  .migrationPlan(migrationPlan)
317:    *  .send();
318:    * </pre>
319:    *
320:    * @param processInstanceKey the key which refers to the process instance to migrate
321:    * @return a builder for the command
322:    */
323:   @ExperimentalApi("https://github.com/camunda/camunda/issues/14907")
324:   MigrateProcessInstanceCommandStep1 newMigrateProcessInstanceCommand(long processInstanceKey);
