813:     if (filter != null) {
814:       if (filter.get$Or() != null && !filter.get$Or().isEmpty()) {
815:         for (final ProcessInstanceFilterFields or : filter.get$Or()) {
816:           final var orBuilder = toProcessInstanceFilterFields(or);
817:           if (orBuilder.isLeft()) {
