819:           } else {
820:             builder.get().addOrOperation(orBuilder.get().build());
821:           }
822:         }
823:       }
824:     }
825: 
826:     return validationErrors.isEmpty()
827:         ? Either.right(builder.get().build())
828:         : Either.left(validationErrors);
829:   }
