219: public final class ServiceTransformers {
220: 
221:   private final Map<Class<?>, ServiceTransformer<?, ?>> transformers = new HashMap<>();
222: 
223:   private ServiceTransformers() {}
224: 
225:   public static ServiceTransformers newInstance(final IndexDescriptors indexDescriptors) {
226:     final var serviceTransformers = new ServiceTransformers();
227:     initializeTransformers(serviceTransformers, indexDescriptors);
228:     return serviceTransformers;
229:   }
230: 
231:   public <F extends FilterBase, S extends SortOption>
232:       TypedSearchQueryTransformer<F, S> getTypedSearchQueryTransformer(final Class<?> cls) {
233:     final ServiceTransformer<TypedSearchQuery<F, S>, SearchQueryRequest> transformer =
234:         getTransformer(cls);
235:     return (TypedSearchQueryTransformer<F, S>) transformer;
236:   }
237: 
238:   public <F extends FilterBase> FilterTransformer<F> getFilterTransformer(final Class<?> cls) {
239:     final ServiceTransformer<F, SearchQuery> transformer = getTransformer(cls);
240:     return (FilterTransformer<F>) transformer;
241:   }
242: 
243:   public <A extends AggregationResultBase>
244:       AggregationResultTransformer<A> getSearchAggregationResultTransformer(final Class<A> cls) {
245:     final ServiceTransformer<Map<String, AggregationResult>, A> transformer = getTransformer(cls);
246:     return (AggregationResultTransformer<A>) transformer;
247:   }
248: 
249:   public <A extends AggregationBase> AggregationTransformer<A> getAggregationTransformer(
250:       final Class<?> cls) {
251:     final ServiceTransformer<A, List<SearchAggregator>> transformer = getTransformer(cls);
252:     return (AggregationTransformer<A>) transformer;
253:   }
254: 
255:   public FieldSortingTransformer getFieldSortingTransformer(final Class<?> cls) {
256:     final ServiceTransformer<String, String> fieldSortingTransformer = getTransformer(cls);
257:     return (FieldSortingTransformer) fieldSortingTransformer;
258:   }
259: 
260:   public <T, R> ServiceTransformer<T, R> getTransformer(final Class<?> cls) {
261:     if (!transformers.containsKey(cls)) {
262:       throw new IllegalArgumentException("No transformer found for class " + cls);
263:     }
264:     return (ServiceTransformer<T, R>) transformers.get(cls);
265:   }
266: 
267:   private void put(final Class<?> cls, final ServiceTransformer<?, ?> mapper) {
268:     transformers.put(cls, mapper);
269:   }
