424:   private void mockCredentials(final String token, final String scope) {
425:     final HashMap<String, String> map = new HashMap<>();
426:     map.put("client_secret", SECRET);
427:     map.put("client_id", CLIENT_ID);
428:     map.put("audience", AUDIENCE);
429:     map.put("grant_type", "client_credentials");
430:     if (scope != null) {
431:       map.put("scope", scope);
432:     }
433: 
434:     final String encodedBody =
435:         map.entrySet().stream()
436:             .map(e -> encode(e.getKey()) + "=" + encode(e.getValue()))
437:             .collect(Collectors.joining("&"));
438: 
439:     map.put("access_token", token);
440:     map.put("token_type", TOKEN_TYPE);
441:     map.put(
442:         "expires_in",
443:         String.valueOf(
444:             EXPIRY.getLong(ChronoField.INSTANT_SECONDS) - Instant.now().getEpochSecond()));
445: 
446:     try {
447:       final String body = jsonMapper.writeValueAsString(map);
448:       currentWiremockRuntimeInfo
449:           .getWireMock()
450:           .register(
451:               WireMock.post(WireMock.urlPathEqualTo("/oauth/token"))
452:                   .withHeader("Content-Type", equalTo("application/x-www-form-urlencoded"))
453:                   .withHeader("Accept", equalTo("application/json"))
454:                   .withHeader("User-Agent", matching("camunda-client-java/\\d+\\.\\d+\\.\\d+.*"))
455:                   .withRequestBody(equalTo(encodedBody))
456:                   .willReturn(
457:                       WireMock.aResponse().withBody(body).withFixedDelay(0).withStatus(200)));
458:     } catch (final JsonProcessingException e) {
459:       throw new RuntimeException(e);
460:     }
461:   }
