463:   private void mockTokenRequest(boolean withAssertion) {
464:     final String assertionRegex = ".*client_assertion\\=[\\._\\-A-Za-z0-9]{400,500}.*";
465:     final String assertionTypeRegex = ".*client_assertion_type.*";
466:     final String clientSecret = ".*client_secret.*";
467:     final HashMap<String, String> map = new HashMap<>();
468:     map.put("access_token", ACCESS_TOKEN);
469:     map.put("token_type", TOKEN_TYPE);
470:     map.put("expires_in", "3600");
471: 
472:     try {
473:       currentWiremockRuntimeInfo
474:           .getWireMock()
475:           .register(
476:               WireMock.post(WireMock.urlPathEqualTo("/oauth/token"))
477:                   .withHeader("Content-Type", equalTo("application/x-www-form-urlencoded"))
478:                   .withHeader("Accept", equalTo("application/json"))
479:                   .withHeader("User-Agent", matching("camunda-client-java/\\d+\\.\\d+\\.\\d+.*"))
480:                   .withRequestBody(
481:                       withAssertion ? matching(assertionRegex) : notMatching(assertionRegex))
482:                   .withRequestBody(
483:                       withAssertion
484:                           ? matching(assertionTypeRegex)
485:                           : notMatching(assertionTypeRegex))
486:                   .withRequestBody(
487:                       !withAssertion ? matching(clientSecret) : notMatching(clientSecret))
488:                   .willReturn(
489:                       WireMock.aResponse()
490:                           .withBody(jsonMapper.writeValueAsString(map))
491:                           .withHeader("Content-Type", "application/json")
492:                           .withStatus(200)));
493:     } catch (JsonProcessingException e) {
494:       throw new RuntimeException(e);
495:     }
496:   }
