498:   private static String encode(final String param) {
499:     try {
500:       return URLEncoder.encode(param, StandardCharsets.UTF_8.name());
501:     } catch (final UnsupportedEncodingException e) {
502:       throw new UncheckedIOException("Failed while encoding OAuth request parameters: ", e);
503:     }
504:   }
