113:   @Override
114:   public void applyCredentials(final CredentialsApplier applier) throws IOException {
115:     final CamundaClientCredentials camundaClientCredentials =
116:         credentialsCache.computeIfMissingOrInvalid(clientId, this::fetchCredentials);
117: 
118:     String type = camundaClientCredentials.getTokenType();
119:     if (type == null || type.isEmpty()) {
120:       throw new IOException(
121:           String.format("Expected valid token type but was absent or invalid '%s'", type));
122:     }
