140:               value -> {
141:                 final CamundaClientCredentials fetchedCredentials = fetchCredentials();
142:                 credentialsCache.put(clientId, fetchedCredentials).writeCache();
143:                 return !fetchedCredentials.equals(value) || !value.isValid();
144:               })
