152:   private static String createParams(final OAuthCredentialsProviderBuilder builder) {
153:     final Map<String, String> payload = new HashMap<>();
154: 
155:     if (builder.entraConfigurationProvided()) {
156:       payload.put(
157:           "client_assertion",
158:           getClientAssertion(
159:               builder.getSslClientCertPath().toAbsolutePath().toString(),
160:               builder.getEntraCertificatePassword(),
161:               builder.getClientId(),
162:               builder.getAudience()));
163:       payload.put("client_assertion_type", JWT_ASSERTION_TYPE);
164:     } else {
165:       payload.put("client_secret", builder.getClientSecret());
166:     }
167: 
168:     payload.put("client_id", builder.getClientId());
169:     payload.put("audience", builder.getAudience());
170:     payload.put("grant_type", "client_credentials");
171:     final String scope = builder.getScope();
172:     if (scope != null) {
173:       payload.put("scope", scope);
174:     }
175: 
176:     return payload.entrySet().stream()
177:         .map(e -> encode(e.getKey()) + "=" + encode(e.getValue()))
178:         .collect(Collectors.joining("&"));
179:   }
