181:   private static String encode(final String param) {
182:     try {
183:       return URLEncoder.encode(param, StandardCharsets.UTF_8.name());
184:     } catch (final UnsupportedEncodingException e) {
185:       throw new UncheckedIOException("Failed while encoding OAuth request parameters: ", e);
186:     }
