189:   private CamundaClientCredentials fetchCredentials() throws IOException {
190:     final HttpURLConnection connection =
191:         (HttpURLConnection) authorizationServerUrl.openConnection();
192:     maybeConfigureCustomSSLContext(connection);
193:     connection.setRequestMethod("POST");
194:     connection.setRequestProperty("Content-Type", "application/x-www-form-urlencoded");
195:     connection.setRequestProperty("Accept", "application/json");
196:     connection.setDoOutput(true);
197:     connection.setReadTimeout(toIntExact(readTimeout.toMillis()));
198:     connection.setConnectTimeout(toIntExact(connectionTimeout.toMillis()));
199:     connection.setRequestProperty("User-Agent", "camunda-client-java/" + VersionUtil.getVersion());
200: 
201:     try (final OutputStream os = connection.getOutputStream()) {
202:       final byte[] input = payload.getBytes(StandardCharsets.UTF_8);
203:       os.write(input, 0, input.length);
204:     }
205: 
206:     if (connection.getResponseCode() != 200) {
207:       throw new IOException(
208:           String.format(
209:               "Failed while requesting access token with status code %d and message %s.",
210:               connection.getResponseCode(), connection.getResponseMessage()));
211:     }
212: 
213:     try (final InputStream in = connection.getInputStream();
214:         final InputStreamReader reader = new InputStreamReader(in, StandardCharsets.UTF_8)) {
215:       final CamundaClientCredentials fetchedCredentials = CREDENTIALS_READER.readValue(reader);
216: 
217:       if (fetchedCredentials == null) {
218:         throw new IOException("Expected valid credentials but got null instead.");
219:       }
220: 
221:       return fetchedCredentials;
222:     }
223:   }
