225:   private void maybeConfigureCustomSSLContext(final HttpURLConnection connection) {
226:     if (connection instanceof HttpsURLConnection) {
227:       final HttpsURLConnection httpsConnection = (HttpsURLConnection) connection;
228:       httpsConnection.setSSLSocketFactory(createSSLContext());
229:     }
