232:   private SSLSocketFactory createSSLContext() {
233:     if (keystorePath == null && truststorePath == null) {
234:       return SSLContexts.createSystemDefault().getSocketFactory();
235:     }
236:     final SSLContextBuilder builder = SSLContexts.custom();
237:     try {
238:       if (keystorePath != null) {
239:         builder.loadKeyMaterial(
240:             keystorePath,
241:             keystorePassword == null ? null : keystorePassword.toCharArray(),
242:             keystoreKeyPassword == null ? new char[0] : keystoreKeyPassword.toCharArray());
243:       }
244:       if (truststorePath != null) {
245:         builder.loadTrustMaterial(
246:             truststorePath, truststorePassword == null ? null : truststorePassword.toCharArray());
247:       }
248:       return builder.build().getSocketFactory();
249:     } catch (final NoSuchAlgorithmException
250:                    | KeyManagementException
251:                    | KeyStoreException
252:                    | UnrecoverableKeyException
253:                    | CertificateException
254:                    | IOException e) {
255:       throw new RuntimeException("Failed to create SSL context", e);
256:     }
257:   }
