259:   private static String getClientAssertion(
260:       final String certPath, final String certStorePassword, final String clientId,
261:       final String audience) {
262:     final X509Certificate certificate;
263:     final Algorithm algorithm;
264:     try (final FileInputStream stream = new FileInputStream(certPath)) {
265:       final KeyStore keyStore = KeyStore.getInstance("PKCS12");
266:       final char[] password = certStorePassword.toCharArray();
267:       keyStore.load(stream, password);
268: 
269:       final String alias = keyStore.aliases().nextElement();
270:       final RSAPrivateKey privateKey = (RSAPrivateKey) keyStore.getKey(alias, password);
271:       final X509Certificate keyStoreCertificate = (X509Certificate) keyStore.getCertificate(alias);
272:       final RSAPublicKey publicKey = (RSAPublicKey) keyStoreCertificate.getPublicKey();
273: 
274:       certificate = (X509Certificate) keyStore.getCertificate(alias);
275:       algorithm = Algorithm.RSA256(publicKey, privateKey);
276:     } catch (final IOException | GeneralSecurityException e) {
277:       throw new RuntimeException("Failed to create client assertion", e);
278:     }
279: 
280:     final Date now = new Date();
281:     final String x5t = generateX5tThumbprint(certificate);
282: 
283:     final Map<String, Object> header = new HashMap<>();
284:     header.put("alg", "RSA256");
285:     header.put("typ", "JWT");
286:     header.put("x5t", x5t);
287: 
288:     return JWT.create()
289:         .withHeader(header)
290:         .withIssuer(clientId)
291:         .withSubject(clientId)
292:         .withAudience(audience)
293:         .withIssuedAt(now)
294:         .withNotBefore(now)
295:         .withExpiresAt(new Date(now.getTime() + 5 * 60 * 1000))
296:         .withJWTId(randomUUID().toString())
297:         .sign(algorithm);
298:   }
299: 
300:   private static String generateX5tThumbprint(final X509Certificate certificate) {
301:     try {
302:       final MessageDigest digest = MessageDigest.getInstance("SHA-1");
303:       final byte[] encoded = digest.digest(certificate.getEncoded());
304:       return Base64.getUrlEncoder().withoutPadding().encodeToString(encoded);
305:     } catch (final Exception e) {
306:       throw new RuntimeException("Failed to generate x5t thumbprint", e);
307:     }
308:   }
309: }
