461:   private void mockTokenRequest(final boolean withAssertion) {
462:     final String assertionRegex = ".*client_assertion\\=[\\._\\-A-Za-z0-9]{400,500}.*";
463:     final String assertionTypeRegex = ".*client_assertion_type.*";
464:     final String clientSecret = ".*client_secret.*";
465:     final HashMap<String, String> map = new HashMap<>();
466:     map.put("access_token", ACCESS_TOKEN);
467:     map.put("token_type", TOKEN_TYPE);
468:     map.put("expires_in", "3600");
