635:   private <I extends Intent> void register(final I intent, final TypedEventApplier<I, ?> applier) {
636:     register(intent, RecordMetadata.DEFAULT_RECORD_VERSION, applier);
637:   }
638: 
639:   <I extends Intent> void register(
640:       final I intent, final int version, final TypedEventApplier<I, ?> applier) {
641:     Objects.requireNonNull(intent, "Intent must not be null");
642:     Objects.requireNonNull(applier, "Applier must not be null");
643:     if (version < 1) {
644:       throw new IllegalArgumentException("Version must be greater than 0");
645:     }
646:     if (!intent.isEvent()) {
647:       throw new IllegalArgumentException("Only event intents can be registered");
648:     }
649: 
650:     final var previousApplier =
651:         mapping.computeIfAbsent(intent, unused -> new HashMap<>()).putIfAbsent(version, applier);
652:     if (previousApplier != null) {
653:       throw new IllegalArgumentException(
654:           String.format(
655:               "Applier for intent '%s' and version '%d' is already registered", intent, version));
656:     }
657:   }
658: 
659:   @Override
660:   public int getLatestVersion(final Intent intent) {
661:     return mapping.getOrDefault(intent, new HashMap<>()).keySet().stream()
662:         .max(Comparator.naturalOrder())
663:         .orElse(-1);
664:   }
665: 
666:   @Override
667:   public void applyState(
668:       final long key, final Intent intent, final RecordValue value, final int recordVersion)
669:       throws NoSuchEventApplier {
670:     final var applierForIntent = mapping.get(intent);
671:     if (applierForIntent == null) {
672:       throw new NoApplierForIntent(intent);
673:     }
674:     final var applierForVersion = applierForIntent.get(recordVersion);
