44: @ExcludeAuthorizationCheck
45: public class UserTaskProcessor implements TypedRecordProcessor<UserTaskRecord> {
46: 
47:   private static final String USER_TASK_COMPLETION_REJECTION =
48:       "Completion of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
49: 
50:   private static final String USER_TASK_ASSIGNMENT_REJECTION =
51:       "Assignment of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
52: 
53:   private static final String USER_TASK_UPDATE_REJECTION =
54:       "Update of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
55: 
56:   private static final String USER_TASK_VARIABLE_UPDATE_REJECTION =
57:       "Variable update for user task instance with key '%d' was denied by Task Listener. Reason to deny: '%s'";
58: 
59:   private final UserTaskCommandProcessors commandProcessors;
60:   private final ProcessState processState;
61:   private final MutableUserTaskState userTaskState;
62:   private final ElementInstanceState elementInstanceState;
63:   private final VariableState variableState;
64: 
65:   private final BpmnJobBehavior jobBehavior;
66: 
67:   private final TypedRejectionWriter rejectionWriter;
68:   private final TypedResponseWriter responseWriter;
69:   private final StateWriter stateWriter;
70: 
71:   public UserTaskProcessor(
72:       final ProcessingState state,
73:       final MutableUserTaskState userTaskState,
74:       final KeyGenerator keyGenerator,
75:       final BpmnBehaviors bpmnBehaviors,
76:       final Writers writers,
77:       final AuthorizationCheckBehavior authCheckBehavior) {
78:     commandProcessors =
79:         new UserTaskCommandProcessors(
80:             state, keyGenerator, bpmnBehaviors, writers, authCheckBehavior);
81:     processState = state.getProcessState();
82:     this.userTaskState = userTaskState;
83:     elementInstanceState = state.getElementInstanceState();
84:     variableState = state.getVariableState();
85: 
86:     jobBehavior = bpmnBehaviors.jobBehavior();
87: 
88:     rejectionWriter = writers.rejection();
89:     responseWriter = writers.response();
90:     stateWriter = writers.state();
91:   }
92: 
93:   @Override
94:   public void processRecord(final TypedRecord<UserTaskRecord> command) {
95:     final UserTaskIntent intentToWrite = (UserTaskIntent) command.getIntent();
96:     switch (intentToWrite) {
97:       case CREATE, ASSIGN, CLAIM, UPDATE, COMPLETE, CANCEL ->
98:           processOperationCommand(command, intentToWrite);
99:       case COMPLETE_TASK_LISTENER -> processCompleteTaskListener(command);
100:       case DENY_TASK_LISTENER -> processDenyTaskListener(command);
101:       default ->
102:           throw new UnsupportedOperationException("Unexpected user task intent: " + intentToWrite);
103:     }
104:   }
105: 
106:   private void processCompleteTaskListener(final TypedRecord<UserTaskRecord> command) {
107:     final var lifecycleState = userTaskState.getLifecycleState(command.getKey());
108:     final var listenerEventType = mapLifecycleStateToEventType(lifecycleState);
109:     // we need to copy the intermediate user task record as we have read it from the state, and we
110:     // will read from the state again later, which in turn would modify this record
111:     final var intermediateUserTaskRecord =
112:         userTaskState.getIntermediateState(command.getKey()).getRecord().copy();
113:     final var userTaskElement = getUserTaskElement(intermediateUserTaskRecord);
114:     final var userTaskElementInstance = getUserTaskElementInstance(intermediateUserTaskRecord);
115:     final var context = buildContext(userTaskElementInstance);
116: 
117:     if (command.getValue().hasChangedAttributes()) {
118:       intermediateUserTaskRecord.wrapChangedAttributesIfValueChanged(command.getValue());
119: 
120:       if (intermediateUserTaskRecord.hasChangedAttributes()) {
121:         stateWriter.appendFollowUpEvent(
122:             command.getKey(), UserTaskIntent.CORRECTED, intermediateUserTaskRecord);
123:       }
124:     }
125: 
126:     findNextTaskListener(listenerEventType, userTaskElement, userTaskElementInstance)
127:         .ifPresentOrElse(
128:             listener -> {
129:               final var currentUserTask = userTaskState.getUserTask(command.getKey());
130:               final var changedAttributes =
131:                   intermediateUserTaskRecord.determineChangedAttributes(currentUserTask);
132:               jobBehavior.createNewTaskListenerJob(
133:                   context, intermediateUserTaskRecord, listener, changedAttributes);
134:             },
135:             () -> finalizeCommand(command, lifecycleState, intermediateUserTaskRecord));
136:   }
137: 
138:   private void finalizeCommand(
139:       final TypedRecord<UserTaskRecord> command,
140:       final LifecycleState lifecycleState,
141:       final UserTaskRecord userTaskRecord) {
142:     final var currentUserTask = userTaskState.getUserTask(command.getKey());
143:     userTaskRecord.setDiffAsChangedAttributes(currentUserTask);
144: 
145:     final var commandProcessor = determineProcessorFromUserTaskLifecycleState(lifecycleState);
146:     commandProcessor.onFinalizeCommand(command, userTaskRecord);
147:   }
148: 
149:   private void processDenyTaskListener(final TypedRecord<UserTaskRecord> command) {
150:     final var lifecycleState = userTaskState.getLifecycleState(command.getKey());
151:     final var persistedRecord = userTaskState.getUserTask(command.getKey());
152: 
153:     switch (lifecycleState) {
154:       case COMPLETING ->
155:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.COMPLETION_DENIED);
156:       case ASSIGNING, CLAIMING ->
157:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.ASSIGNMENT_DENIED);
158:       case UPDATING ->
159:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.UPDATE_DENIED);
160:       default -> throw new IllegalArgumentException(
161:           "Expected to reject operation for user task: '%d', but operation could not be determined from the task's current lifecycle state: '%s'"
162:               .formatted(command.getValue().getUserTaskKey(), lifecycleState));
163:     }
164:   }
165: 
166:   private void processOperationCommand(
167:       final TypedRecord<UserTaskRecord> command, final UserTaskIntent intentToWrite) {
168:     final var commandProcessor = commandProcessors.getCommandProcessor(intentToWrite);
169: 
170:     if (isRetriedCommand(command)) {
171:       // Skip `validateCommand` and `onCommand` invocations for retried command,
172:       // as it was already validated during the original execution
173:       finalizeCommandOrCreateTaskListenerJob(commandProcessor, command, command.getValue(),
174:           intentToWrite);
175:     } else {
176:       commandProcessor
177:           .validateCommand(command)
178:           // Create a modifiable copy of the persisted user task record, as `onCommand` may
179:           // apply the changed attributes from the command on top of persisted instance.
180:           .map(UserTaskRecord::copy)
181:           .thenDo(persistedRecord -> commandProcessor.onCommand(command, persistedRecord))
182:           .ifRightOrLeft(
183:               persistedRecord ->
184:                   finalizeCommandOrCreateTaskListenerJob(
185:                       commandProcessor, command, persistedRecord, intentToWrite),
186:               rejection -> handleCommandRejection(command, rejection));
187:     }
188:   }
189: 
190:   private void finalizeCommandOrCreateTaskListenerJob(
191:       final UserTaskCommandProcessor processor,
192:       final TypedRecord<UserTaskRecord> command,
193:       final UserTaskRecord persistedRecord,
194:       final UserTaskIntent intentToWrite) {
195: 
196:     final var userTaskElement = getUserTaskElement(persistedRecord);
197:     final var eventType = mapIntentToEventType(intentToWrite);
198: 
199:     if (userTaskElement.hasTaskListeners(eventType)) {
200:       /*
201:        * Store the original command's metadata (requestId, requestStreamId) before creating
202:        * the first task listener job. This metadata will be used later to finalize the original
203:        * command after all task listeners have been processed, ensuring that the engine can respond
204:        * appropriately to the original command request.
205:        *
206:        * Note:
207:        * Typically, persistence logic should be handled via `*Applier` classes. However, since
208:        * this involves request-related data, so in the case of command reconstruction,
209:        * we will have new request values anyway, so persisting these data here is acceptable.
210:        * A similar approach has been used in `ProcessInstanceCreationCreateWithResultProcessor`.
211:        */
212:       storeUserTaskRecordRequestMetadata(command);
213: 
214:       final var listener = userTaskElement.getTaskListeners(eventType).getFirst();
215:       final var userTaskElementInstance = getUserTaskElementInstance(persistedRecord);
216:       final var context = buildContext(userTaskElementInstance);
217:       jobBehavior.createNewTaskListenerJob(
218:           context, persistedRecord, listener, persistedRecord.getChangedAttributes());
219:     } else {
220:       processor.onFinalizeCommand(command, persistedRecord);
221:     }
222:   }
223: 
224:   private boolean isRetriedCommand(final TypedRecord<UserTaskRecord> command) {
225:     return command instanceof RetryTypedRecord<UserTaskRecord>;
226:   }
227: 
228:   private void storeUserTaskRecordRequestMetadata(final TypedRecord<UserTaskRecord> command) {
229:     if (!command.hasRequestMetadata()) {
230:       return;
231:     }
232: 
233:     final var metadata =
234:         new UserTaskTransitionTriggerRequestMetadata()
235:             .setIntent(command.getIntent())
236:             .setTriggerType(ValueType.USER_TASK)
237:             .setRequestId(command.getRequestId())
238:             .setRequestStreamId(command.getRequestStreamId());
239:     userTaskState.storeRecordRequestMetadata(command.getValue().getUserTaskKey(), metadata);
240:   }
241: 
242:   private void handleCommandRejection(
243:       final TypedRecord<UserTaskRecord> command, final Rejection rejection) {
244:     rejectionWriter.appendRejection(command, rejection.type(), rejection.reason());
245:     responseWriter.writeRejectionOnCommand(command, rejection.type(), rejection.reason());
246:   }
247: 
248:   private Optional<TaskListener> findNextTaskListener(
249:       final ZeebeTaskListenerEventType eventType,
250:       final ExecutableUserTask userTask,
251:       final ElementInstance userTaskElementInstance) {
252:     final var listeners = userTask.getTaskListeners(eventType);
253:     final int currentListenerIndex = userTaskElementInstance.getTaskListenerIndex(eventType);
254:     return listeners.stream().skip(currentListenerIndex).findFirst();
255:   }
256: 
257:   private void writeRejectionForCommand(
258:       final TypedRecord<UserTaskRecord> command,
259:       final UserTaskRecord persistedRecord,
260:       final UserTaskIntent intentToWrite) {
261: 
262:     persistedRecord.setDeniedReason(command.getValue().getDeniedReason());
263:     final var recordRequestMetadata =
264:         userTaskState.findRecordRequestMetadata(persistedRecord.getUserTaskKey());
265: 
266:     stateWriter.appendFollowUpEvent(persistedRecord.getUserTaskKey(), intentToWrite,
267:         persistedRecord);
268:     recordRequestMetadata.ifPresent(
269:         metadata -> {
270:           switch (metadata.getTriggerType()) {
271:             case USER_TASK -> responseWriter.writeRejection(
272:                 command.getKey(),
273:                 mapDeniedIntentToResponseIntent(intentToWrite),
274:                 command.getValue(),
275:                 command.getValueType(),
276:                 RejectionType.INVALID_STATE,
277:                 mapDeniedIntentToResponseRejectionReason(
278:                     intentToWrite,
279:                     persistedRecord.getUserTaskKey(),
280:                     command.getValue().getDeniedReason()),
281:                 metadata.getRequestId(),
282:                 metadata.getRequestStreamId());
283:             case VARIABLE_DOCUMENT -> {
284:               final long userTaskInstanceKey = command.getValue().getElementInstanceKey();
285:               variableState
286:                   .findVariableDocumentState(userTaskInstanceKey)
287:                   .ifPresent(
288:                       variableDocumentState -> {
289:                         final long variableDocumentKey = variableDocumentState.getKey();
290:                         final var variableDocumentRecord = variableDocumentState.getRecord();
291:                         stateWriter.appendFollowUpEvent(
292:                             variableDocumentKey,
293:                             VariableDocumentIntent.UPDATE_DENIED,
294:                             variableDocumentRecord);
295: 
296:                         final var deniedReason =
297:                             USER_TASK_VARIABLE_UPDATE_REJECTION.formatted(
298:                                 userTaskInstanceKey, command.getValue().getDeniedReason());
299:                         responseWriter.writeRejection(
300:                             variableDocumentKey,
301:                             VariableDocumentIntent.UPDATE,
302:                             variableDocumentRecord,
303:                             ValueType.VARIABLE_DOCUMENT,
304:                             RejectionType.INVALID_STATE,
305:                             deniedReason,
306:                             metadata.getRequestId(),
307:                             metadata.getRequestStreamId());
308:                       });
309:             }
310:             default -> throw new IllegalArgumentException(
311:                 "Unexpected user task transition trigger type: '%s'"
312:                     .formatted(metadata.getTriggerType()));
313:           }
314:         });
315:   }
