317:   private ExecutableUserTask getUserTaskElement(final UserTaskRecord userTaskRecord) {
318:     return processState.getFlowElement(
319:         userTaskRecord.getProcessDefinitionKey(),
320:         userTaskRecord.getTenantId(),
321:         userTaskRecord.getElementIdBuffer(),
322:         ExecutableUserTask.class);
323:   }
324: 
325:   private ZeebeTaskListenerEventType mapIntentToEventType(final UserTaskIntent intentToWrite) {
326:     return switch (intentToWrite) {
327:       case CREATE -> ZeebeTaskListenerEventType.creating;
328:       case ASSIGN, CLAIM -> ZeebeTaskListenerEventType.assigning;
329:       case UPDATE -> ZeebeTaskListenerEventType.updating;
330:       case COMPLETE -> ZeebeTaskListenerEventType.completing;
331:       case CANCEL -> ZeebeTaskListenerEventType.canceling;
332:       default -> throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(
333:           intentToWrite));
334:     };
335:   }
336: 
337:   private ZeebeTaskListenerEventType mapLifecycleStateToEventType(
338:       final LifecycleState lifecycleState) {
339:     return switch (lifecycleState) {
340:       case CREATING -> ZeebeTaskListenerEventType.creating;
341:       case ASSIGNING, CLAIMING -> ZeebeTaskListenerEventType.assigning;
342:       case UPDATING -> ZeebeTaskListenerEventType.updating;
343:       case COMPLETING -> ZeebeTaskListenerEventType.completing;
344:       case CANCELING -> ZeebeTaskListenerEventType.canceling;
345:       default -> throw new IllegalArgumentException(
346:           "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
347:     };
348:   }
349: 
350:   private UserTaskIntent mapDeniedIntentToResponseIntent(final UserTaskIntent intentToWrite) {
351:     return switch (intentToWrite) {
352:       case COMPLETION_DENIED -> UserTaskIntent.COMPLETE;
353:       case ASSIGNMENT_DENIED -> UserTaskIntent.ASSIGN;
354:       case UPDATE_DENIED -> UserTaskIntent.UPDATE;
355:       default -> throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(
356:           intentToWrite));
357:     };
358:   }
359: 
360:   private String mapDeniedIntentToResponseRejectionReason(
361:       final UserTaskIntent intent, final long userTaskKey, final String deniedReason) {
362:     return switch (intent) {
363:       case COMPLETION_DENIED -> USER_TASK_COMPLETION_REJECTION.formatted(userTaskKey, deniedReason);
364:       case ASSIGNMENT_DENIED -> USER_TASK_ASSIGNMENT_REJECTION.formatted(userTaskKey, deniedReason);
365:       case UPDATE_DENIED -> USER_TASK_UPDATE_REJECTION.formatted(userTaskKey, deniedReason);
366:       default ->
367:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
368:     };
369:   }
370: 
371:   private UserTaskCommandProcessor determineProcessorFromUserTaskLifecycleState(
372:       final LifecycleState lifecycleState) {
373: 
374:     final var userTaskIntent =
375:         switch (lifecycleState) {
376:           case CREATING -> UserTaskIntent.CREATE;
377:           case ASSIGNING -> UserTaskIntent.ASSIGN;
378:           case CLAIMING -> UserTaskIntent.CLAIM;
379:           case UPDATING -> UserTaskIntent.UPDATE;
380:           case COMPLETING -> UserTaskIntent.COMPLETE;
381:           case CANCELING -> UserTaskIntent.CANCEL;
382:           default -> throw new IllegalArgumentException(
383:               "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
384:         };
385: 
386:     return commandProcessors.getCommandProcessor(userTaskIntent);
387:   }
388: 
389:   private ElementInstance getUserTaskElementInstance(final UserTaskRecord userTaskRecord) {
390:     final var elementInstanceKey = userTaskRecord.getElementInstanceKey();
391:     return elementInstanceState.getInstance(elementInstanceKey);
392:   }
393: 
394:   private BpmnElementContext buildContext(final ElementInstance elementInstance) {
395:     final var context = new BpmnElementContextImpl();
396:     context.init(elementInstance.getKey(), elementInstance.getValue(), elementInstance.getState());
397:     return context;
398:   }
