33: public class DecisionEvaluationEvaluteProcessor
34:     implements TypedRecordProcessor<DecisionEvaluationRecord> {
35: 
36:   private static final String ERROR_MESSAGE_NO_IDENTIFIER_SPECIFIED =
37:       "Expected either a decision id or a valid decision key, but none provided";
38: 
39:   private final DecisionBehavior decisionBehavior;
40:   private final TypedRejectionWriter rejectionWriter;
41:   private final TypedResponseWriter responseWriter;
42:   private final AuthorizationCheckBehavior authCheckBehavior;
43:   private final StateWriter stateWriter;
44:   private final KeyGenerator keyGenerator;
45: 
46:   public DecisionEvaluationEvaluteProcessor(
47:       final DecisionBehavior decisionBehavior,
48:       final KeyGenerator keyGenerator,
49:       final Writers writers,
50:       final AuthorizationCheckBehavior authCheckBehavior) {
51: 
52:     this.decisionBehavior = decisionBehavior;
53:     this.keyGenerator = keyGenerator;
54:     stateWriter = writers.state();
55:     rejectionWriter = writers.rejection();
56:     responseWriter = writers.response();
57:     this.authCheckBehavior = authCheckBehavior;
58:   }
59: 
60:   @Override
61:   public void processRecord(final TypedRecord<DecisionEvaluationRecord> command) {
62: 
63:     final DecisionEvaluationRecord record = command.getValue();
64:     final var decisionOrFailure = getDecision(record);
65: 
66:     if (decisionOrFailure.isRight()) {
67:       final var decision = decisionOrFailure.get();
68:       final var decisionId = bufferAsString(decision.getDecisionId());
69:       final var authRequest =
70:           new AuthorizationRequest(
71:                   command,
72:                   AuthorizationResourceType.DECISION_DEFINITION,
73:                   PermissionType.CREATE_DECISION_INSTANCE,
74:                   record.getTenantId())
75:               .addResourceId(decisionId);
76: 
77:       final var isAuthorized = authCheckBehavior.isAuthorized(authRequest);
78:       if (isAuthorized.isLeft()) {
79:         final var rejection = isAuthorized.getLeft();
80:         final String errorMessage =
81:             RejectionType.NOT_FOUND.equals(rejection.type())
82:                 ? AuthorizationCheckBehavior.NOT_FOUND_ERROR_MESSAGE.formatted(
83:                     "evaluate a decision", record.getDecisionKey(), "such decision")
84:                 : rejection.reason();
85:         responseWriter.writeRejectionOnCommand(command, rejection.type(), errorMessage);
86:         rejectionWriter.appendRejection(command, rejection.type(), errorMessage);
87:         return;
88:       }
89:     }
90: 
91:     decisionOrFailure
92:         .flatMap(
93:             decision ->
94:                 decisionBehavior
95:                     .findParsedDrgByDecision(decision)
96:                     .mapLeft(
97:                         failure -> new Rejection(RejectionType.NOT_FOUND, failure.getMessage())))
98:         .ifRightOrLeft(
99:             drg -> {
100:               final var decision = decisionOrFailure.get();
101:               final var variables = record.getVariablesBuffer();
102:               final var evaluationResult =
103:                   decisionBehavior.evaluateDecisionInDrg(
104:                       drg, BufferUtil.bufferAsString(decision.getDecisionId()), variables);
105: 
106:               final Tuple<DecisionEvaluationIntent, DecisionEvaluationRecord>
107:                   evaluationRecordTuple =
108:                       decisionBehavior.createDecisionEvaluationEvent(decision, evaluationResult);
109: 
110:               final var evaluationRecordKey = keyGenerator.nextKey();
111:               stateWriter.appendFollowUpEvent(
112:                   evaluationRecordKey,
113:                   evaluationRecordTuple.getLeft(),
114:                   evaluationRecordTuple.getRight());
115:               responseWriter.writeEventOnCommand(
116:                   evaluationRecordKey,
117:                   evaluationRecordTuple.getLeft(),
118:                   evaluationRecordTuple.getRight(),
119:                   command);
120:             },
121:             rejection -> {
122:               final String reason = rejection.reason();
123:               responseWriter.writeRejectionOnCommand(command, rejection.type(), reason);
124:               rejectionWriter.appendRejection(command, rejection.type(), reason);
125:             });
126:   }
127: 
128:   private Either<Rejection, PersistedDecision> getDecision(final DecisionEvaluationRecord record) {
129: 
130:     final String decisionId = record.getDecisionId();
131:     final long decisionKey = record.getDecisionKey();
132: 
133:     if (!decisionId.isEmpty()) {
134:       return decisionBehavior
135:           .findLatestDecisionByIdAndTenant(decisionId, record.getTenantId())
136:           .mapLeft(failure -> new Rejection(RejectionType.NOT_FOUND, failure.getMessage()));
137:       // TODO: expand DecisionState API to find decisions by ID AND VERSION (#11230)
138:     } else if (decisionKey > -1L) {
139:       return decisionBehavior
140:           .findDecisionByKeyAndTenant(decisionKey, record.getTenantId())
141:           .mapLeft(failure -> new Rejection(RejectionType.NOT_FOUND, failure.getMessage()));
142:     } else {
143:       // if both ID and KEY are missing
144:       return Either.left(
145:           new Rejection(RejectionType.INVALID_ARGUMENT, ERROR_MESSAGE_NO_IDENTIFIER_SPECIFIED));
146:     }
147:   }
148: }
