44: 
45:   private static final String ERROR_MESSAGE_SCOPE_NOT_FOUND =
46:       "Expected to update variables for element with key '%d', but no such element was found";
47: 
48:   private static final String INVALID_USER_TASK_STATE_MESSAGE =
49:       "Expected to trigger update transition for user task with key '%d', but it is in state '%s'";
50: 
51:   private final ElementInstanceState elementInstanceState;
52:   private final MutableUserTaskState userTaskState;
53:   private final ProcessState processState;
54:   private final KeyGenerator keyGenerator;
55:   private final VariableBehavior variableBehavior;
56:   private final BpmnJobBehavior jobBehavior;
57:   private final Writers writers;
58:   private final AuthorizationCheckBehavior authCheckBehavior;
59: 
60:   public VariableDocumentUpdateProcessor(
61:       final ProcessingState processingState,
62:       final KeyGenerator keyGenerator,
63:       final BpmnBehaviors bpmnBehaviors,
64:       final Writers writers,
65:       final MutableUserTaskState userTaskState,
66:       final AuthorizationCheckBehavior authCheckBehavior) {
67:     elementInstanceState = processingState.getElementInstanceState();
68:     this.userTaskState = userTaskState;
69:     processState = processingState.getProcessState();
70:     this.keyGenerator = keyGenerator;
71:     variableBehavior = bpmnBehaviors.variableBehavior();
72:     jobBehavior = bpmnBehaviors.jobBehavior();
73:     this.writers = writers;
74:     this.authCheckBehavior = authCheckBehavior;
75:   }
76: 
77:   @Override
78:   public void processRecord(final TypedRecord<VariableDocumentRecord> record) {
79:     final VariableDocumentRecord value = record.getValue();
80: 
81:     final ElementInstance scope = elementInstanceState.getInstance(value.getScopeKey());
82:     if (scope == null || scope.isTerminating() || scope.isInFinalState()) {
83:       final String reason = String.format(ERROR_MESSAGE_SCOPE_NOT_FOUND, value.getScopeKey());
84:       writers.rejection().appendRejection(record, RejectionType.NOT_FOUND, reason);
85:       writers.response().writeRejectionOnCommand(record, RejectionType.NOT_FOUND, reason);
86:       return;
87:     }
88: 
89:     final var authRequest =
90:         new AuthorizationRequest(
91:             record,
92:             AuthorizationResourceType.PROCESS_DEFINITION,
93:             PermissionType.UPDATE_PROCESS_INSTANCE,
94:             scope.getValue().getTenantId())
95:             .addResourceId(scope.getValue().getBpmnProcessId());
96:     final var isAuthorized = authCheckBehavior.isAuthorized(authRequest);
97:     if (isAuthorized.isLeft()) {
98:       final var rejection = isAuthorized.getLeft();
99:       final String errorMessage =
100:           RejectionType.NOT_FOUND.equals(rejection.type())
101:               ? AuthorizationCheckBehavior.NOT_FOUND_ERROR_MESSAGE.formatted(
102:               "update variables for element",
103:               scope.getValue().getProcessInstanceKey(),
104:               "such element")
105:               : rejection.reason();
106:       writers.rejection().appendRejection(record, rejection.type(), errorMessage);
107:       writers.response().writeRejectionOnCommand(record, rejection.type(), errorMessage);
108:       return;
109:     }
110: 
111:     final String tenantId = scope.getValue().getTenantId();
112: 
113:     if (isCamundaUserTask(scope)) {
114:       final long userTaskKey = scope.getUserTaskKey();
115:       final var lifecycleState = userTaskState.getLifecycleState(userTaskKey);
116:       if (lifecycleState != LifecycleState.CREATED) {
117:         final var reason = INVALID_USER_TASK_STATE_MESSAGE.formatted(userTaskKey, lifecycleState);
118:         writers.rejection().appendRejection(record, RejectionType.INVALID_STATE, reason);
119:         writers.response().writeRejectionOnCommand(record, RejectionType.INVALID_STATE, reason);
120:         return;
121:       }
122: 
123:       final long key = keyGenerator.nextKey();
124:       writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATING, value);
125: 
126:       final var userTaskRecord = userTaskState.getUserTask(userTaskKey);
127:       if (hasVariables(value)) {
128:         userTaskRecord.setVariables(value.getVariablesBuffer()).setVariablesChanged();
129:       }
130:       writers.state().appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATING, userTaskRecord);
131: 
132:       final var userTaskElement =
133:           processState.getFlowElement(
134:               userTaskRecord.getProcessDefinitionKey(),
135:               tenantId,
136:               userTaskRecord.getElementIdBuffer(),
137:               ExecutableUserTask.class);
138: 
139:       if (userTaskElement.hasTaskListeners(ZeebeTaskListenerEventType.updating)) {
140:         storeRecordRequestMetadata(userTaskKey, record);
141: 
142:         final var listener =
143:             userTaskElement.getTaskListeners(ZeebeTaskListenerEventType.updating).getFirst();
144:         jobBehavior.createNewTaskListenerJob(
145:             buildContext(scope), userTaskRecord, listener, userTaskRecord.getChangedAttributes());
146:         return;
147:       }
148: 
149:       switch (value.getUpdateSemantics()) {
150:         case LOCAL -> variableBehavior.mergeLocalDocument(
151:             userTaskRecord.getElementInstanceKey(),
152:             userTaskRecord.getProcessDefinitionKey(),
153:             userTaskRecord.getProcessInstanceKey(),
154:             userTaskRecord.getBpmnProcessIdBuffer(),
155:             userTaskRecord.getTenantId(),
156:             value.getVariablesBuffer());
157:         case PROPAGATE -> variableBehavior.mergeDocument(
158:             userTaskRecord.getElementInstanceKey(),
159:             userTaskRecord.getProcessDefinitionKey(),
160:             userTaskRecord.getProcessInstanceKey(),
161:             userTaskRecord.getBpmnProcessIdBuffer(),
162:             userTaskRecord.getTenantId(),
163:             value.getVariablesBuffer());
164:         default -> throw new IllegalStateException(
165:             "Unexpected variable update semantic: '%s'. Expected either 'LOCAL' or 'PROPAGATE'."
166:                 .formatted(value.getUpdateSemantics()));
167:       }
168: 
169:       writers
170:           .state()
171:           .appendFollowUpEvent(scope.getUserTaskKey(), UserTaskIntent.UPDATED, userTaskRecord);
172: 
173:       writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATED, value);
174:       writers.response().writeEventOnCommand(key, VariableDocumentIntent.UPDATED, value, record);
175:       return;
176:     }
177: 
178:     final long processDefinitionKey = scope.getValue().getProcessDefinitionKey();
179:     final long processInstanceKey = scope.getValue().getProcessInstanceKey();
180:     final DirectBuffer bpmnProcessId = scope.getValue().getBpmnProcessIdBuffer();
181:     try {
182:       if (value.getUpdateSemantics() == VariableDocumentUpdateSemantic.LOCAL) {
183:         variableBehavior.mergeLocalDocument(
184:             scope.getKey(),
185:             processDefinitionKey,
186:             processInstanceKey,
187:             bpmnProcessId,
188:             tenantId,
189:             value.getVariablesBuffer());
190:       } else {
191:         variableBehavior.mergeDocument(
192:             scope.getKey(),
193:             processDefinitionKey,
194:             processInstanceKey,
195:             bpmnProcessId,
196:             tenantId,
197:             value.getVariablesBuffer());
198:       }
199:     } catch (final MsgpackReaderException e) {
200:       final String reason =
201:           String.format(
202:               "Expected document to be valid msgpack, but it could not be read: '%s'",
203:               e.getMessage());
204:       writers.rejection().appendRejection(record, RejectionType.INVALID_ARGUMENT, reason);
205:       writers.response().writeRejectionOnCommand(record, RejectionType.INVALID_ARGUMENT, reason);
206:       return;
207:     }
208: 
209:     final long key = keyGenerator.nextKey();
210: 
211:     writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATED, value);
212:     writers.response().writeEventOnCommand(key, VariableDocumentIntent.UPDATED, value, record);
213:   }
214: 
215:   private static boolean hasVariables(final VariableDocumentRecord record) {
216:     return !DocumentValue.EMPTY_DOCUMENT.equals(record.getVariablesBuffer());
217:   }
218: 
219:   private static boolean isCamundaUserTask(final ElementInstance elementInstance) {
220:     return elementInstance.getValue().getBpmnElementType() == BpmnElementType.USER_TASK
221:         && elementInstance.getUserTaskKey() > -1L;
222:   }
223: 
224:   private static BpmnElementContext buildContext(final ElementInstance elementInstance) {
225:     final var context = new BpmnElementContextImpl();
226:     context.init(elementInstance.getKey(), elementInstance.getValue(), elementInstance.getState());
227:     return context;
228:   }
229: 
230:   void storeRecordRequestMetadata(
231:       final long userTaskKey, final TypedRecord<VariableDocumentRecord> command) {
232:     if (!command.hasRequest()) {
233:       return;
234:     }
235: 
236:     final var metadata =
237:         new UserTaskTransitionTriggerRequestMetadata()
238:             .setIntent(command.getIntent())
239:             .setTriggerType(ValueType.VARIABLE_DOCUMENT)
240:             .setRequestId(command.getRequestId())
241:             .setRequestStreamId(command.getRequestStreamId());
242:     userTaskState.storeRecordRequestMetadata(userTaskKey, metadata);
243:   }
244: }
