202:   private void transformAndDistributeDeployment(final TypedRecord<DeploymentRecord> command) {
203:     final DeploymentRecord deploymentEvent = command.getValue();
204:     final long key = keyGenerator.nextKey();
205:     deploymentEvent.setDeploymentKey(key);
206: 
207:     // Note: transforming a resource will also write the CREATE events for said resource
208:     final Either<Failure, Void> result = deploymentTransformer.transform(deploymentEvent);
209: 
210:     if (result.isLeft()) {
211:       throw new ResourceTransformationFailedException(result.getLeft().getMessage());
212:     }
213: 
214:     try {
215:       createTimerIfTimerStartEvent(command);
216:     } catch (final RuntimeException e) {
217:       final String reason = String.format(COULD_NOT_CREATE_TIMER_MESSAGE, e.getMessage());
218:       throw new TimerCreationFailedException(reason);
219:     }
220: 
221:     final var recordWithoutResource = createDeploymentWithoutResources(deploymentEvent);
222:     responseWriter.writeEventOnCommand(
223:         key, DeploymentIntent.CREATED, recordWithoutResource, command);
224:     stateWriter.appendFollowUpEvent(key, DeploymentIntent.CREATED, recordWithoutResource);
225: 
226:     distributionBehavior.withKey(key).inQueue(DistributionQueue.DEPLOYMENT).distribute(command);
227:   }
