233:     createFormResources(deploymentEvent);
234:     createResources(deploymentEvent);
235:     final var recordWithoutResource = createDeploymentWithoutResources(deploymentEvent);
236:     stateWriter.appendFollowUpEvent(
237:         command.getKey(), DeploymentIntent.CREATED, recordWithoutResource);
238:     distributionBehavior.acknowledgeCommand(command);
239:   }
