245:             metadata -> {
246:               for (final DeploymentResource resource : deploymentEvent.getResources()) {
247:                 final var resourceChecksum =
248:                     deploymentTransformer.getChecksum(resource.getResource());
249:                 if (resourceChecksum.equals(metadata.getChecksumBuffer())) {
250:                   stateWriter.appendFollowUpEvent(
251:                       metadata.getKey(),
252:                       ProcessIntent.CREATED,
253:                       new ProcessRecord().wrap(metadata, resource.getResource()));
254:                 }
255:               }
256:             });
