342:   private void subscribeToTimerStartEventIfExists(
343:       final ProcessMetadata processMetadata, final List<ExecutableStartEvent> startEvents) {
344:     for (final ExecutableCatchEventElement startEvent : startEvents) {
345:       if (startEvent.isTimer()) {
346:         // There are no variables when there is no process instance yet,
347:         // we use a negative scope key to indicate this
348:         final long scopeKey = -1L;
349:         final Either<Failure, Timer> timerOrError =
350:             startEvent.getTimerFactory().apply(expressionProcessor, scopeKey);
351:         if (timerOrError.isLeft()) {
352:           // todo(#4323): deal with this exceptional case without throwing an exception
353:           throw new EvaluationException(timerOrError.getLeft().getMessage());
354:         }
