356:         catchEventBehavior.subscribeToTimerEvent(
357:             NO_ELEMENT_INSTANCE,
358:             NO_ELEMENT_INSTANCE,
359:             processMetadata.getKey(),
360:             startEvent.getId(),
361:             processMetadata.getTenantId(),
362:             timerOrError.get());
