34:   public CheckpointCreateProcessor(
35:       final CheckpointState checkpointState,
36:       final BackupManager backupManager,
37:       final Set<CheckpointListener> listeners,
38:       final CheckpointMetrics metrics) {
39:     this.checkpointState = checkpointState;
40:     this.backupManager = backupManager;
41:     this.listeners = listeners;
42:     this.metrics = metrics;
43:   }
44: 
45:   public ProcessingResult process(
46:       final TypedRecord<CheckpointRecord> record, final ProcessingResultBuilder resultBuilder) {
47: 
48:     final var checkpointRecord = record.getValue();
49:     final long checkpointId = checkpointRecord.getCheckpointId();
50:     if (checkpointState.getCheckpointId() < checkpointId) {
51:       // Only take a checkpoint if it is newer
52:       final var checkpointPosition = record.getPosition();
53:       backupManager.takeBackup(checkpointId, checkpointPosition);
54:       checkpointState.setCheckpointInfo(checkpointId, checkpointPosition);
55: 
56:       // Notify listeners immediately
57:       listeners.forEach(l -> l.onNewCheckpointCreated(checkpointId));
58: 
59:       metrics.created(checkpointId, checkpointPosition);
60: 
61:       final var followupRecord =
62:           new CheckpointRecord()
63:               .setCheckpointId(checkpointId)
64:               .setCheckpointPosition(checkpointPosition);
65:       return createFollowUpAndResponse(
66:           record, CheckpointIntent.CREATED, followupRecord, resultBuilder);
67:     } else {
68:       metrics.ignored();
69:       // A checkpoint already exists. Ignore the command. Use the latest checkpoint info in
70:       // the record so that the response sent contains the latest checkpointId. This is useful to
71:       // return useful information back to the client.
72:       return createFollowUpAndResponse(
73:           record,
74:           CheckpointIntent.IGNORED,
75:           new CheckpointRecord()
76:               .setCheckpointId(checkpointState.getCheckpointId())
77:               .setCheckpointPosition(checkpointState.getCheckpointPosition()),
78:           resultBuilder);
79:     }
80:   }
