82:   private ProcessingResult createFollowUpAndResponse(
83:       final TypedRecord<CheckpointRecord> command,
84:       final CheckpointIntent resultIntent,
85:       final CheckpointRecord checkpointRecord,
86:       final ProcessingResultBuilder resultBuilder) {
87:     resultBuilder.appendRecord(
88:         command.getKey(),
89:         checkpointRecord,
90:         new RecordMetadata()
91:             .recordType(RecordType.EVENT)
92:             .intent(resultIntent)
93:             .rejectionType(RejectionType.NULL_VAL)
94:             .rejectionReason("")
95:             .operationReference(command.getOperationReference()));
