255:   private void writeRejectionForCommand(
256:       final TypedRecord<UserTaskRecord> command,
257:       final UserTaskRecord persistedRecord,
258:       final UserTaskIntent intent) {
259: 
260:     persistedRecord.setDeniedReason(command.getValue().getDeniedReason());
261:     final var recordRequestMetadata =
262:         userTaskState.findAsyncRequest(persistedRecord.getUserTaskKey());
263: 
264:     stateWriter.appendFollowUpEvent(persistedRecord.getUserTaskKey(), intent, persistedRecord);
265:     recordRequestMetadata.ifPresent(
266:         metadata -> {
267:           switch (metadata.getTriggerType()) {
268:             case USER_TASK -> responseWriter.writeRejection(
269:                 command.getKey(),
270:                 mapDeniedIntentToResponseIntent(intent),
271:                 command.getValue(),
272:                 command.getValueType(),
273:                 RejectionType.INVALID_STATE,
274:                 mapDeniedIntentToResponseRejectionReason(
275:                     intent,
276:                     persistedRecord.getUserTaskKey(),
277:                     command.getValue().getDeniedReason()),
278:                 metadata.getRequestId(),
279:                 metadata.getRequestStreamId());
280:             case VARIABLE_DOCUMENT -> {
281:               final long userTaskInstanceKey = command.getValue().getElementInstanceKey();
282:               variableState
283:                   .findVariableDocumentState(userTaskInstanceKey)
284:                   .ifPresent(
285:                       variableDocumentState -> {
286:                         final long variableDocumentKey = variableDocumentState.getKey();
287:                         final var variableDocumentRecord = variableDocumentState.getRecord();
288:                         stateWriter.appendFollowUpEvent(
289:                             variableDocumentKey,
290:                             VariableDocumentIntent.UPDATE_DENIED,
291:                             variableDocumentRecord);
292: 
293:                         final var deniedReason =
294:                             USER_TASK_VARIABLE_UPDATE_REJECTION.formatted(
295:                                 userTaskInstanceKey, command.getValue().getDeniedReason());
296:                         responseWriter.writeRejection(
297:                             variableDocumentKey,
298:                             VariableDocumentIntent.UPDATE,
299:                             variableDocumentRecord,
300:                             ValueType.VARIABLE_DOCUMENT,
301:                             RejectionType.INVALID_STATE,
302:                             deniedReason,
303:                             metadata.getRequestId(),
304:                             metadata.getRequestStreamId());
305:                       });
306:             }
307:             default -> throw new IllegalArgumentException(
308:                 "Unexpected user task transition trigger type: '%s'"
309:                     .formatted(metadata.getTriggerType()));
310:           }
311:         });
312:   }
