362:       case UPDATE_DENIED -> USER_TASK_UPDATE_REJECTION.formatted(userTaskKey, deniedReason);
363:       default ->
364:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
365:     };
366:   }
