248:           .map(
249:               clientId ->
250:                   getAuthorizedResourceIdentifiers(
251:                       EntityType.CLIENT,
252:                       clientId,
253:                       request.getResourceType(),
254:                       request.getPermissionType()))
255:           .ifPresent(idsForClientId -> idsForClientId.forEach(authorizedResourceIds::add));
256:     }
257: 
258:     // mappings can layer on top of username/client id
259:     getPersistedMappings(request)
260:         .flatMap(
261:             mapping ->
262:                 getAuthorizedResourceIdentifiers(
263:                     EntityType.MAPPING,
264:                     mapping.getMappingId(),
265:                     request.getResourceType(),
266:                     request.getPermissionType()))
267:         .forEach(authorizedResourceIds::add);
