272:   /**
273:    * Get direct authorized resource identifiers for a given owner, resource type and permission
274:    * type. This does not include inherited authorizations, for example authorizations for users from
275:    * assigned roles or groups.
276:    */
277:   public Set<String> getDirectAuthorizedResourceIdentifiers(
278:       final AuthorizationOwnerType ownerType,
279:       final String ownerId,
280:       final AuthorizationResourceType resourceType,
281:       final PermissionType permissionType) {
282:     return authorizationState.getResourceIdentifiers(
283:         ownerType, ownerId, resourceType, permissionType);
284:   }
