286:   private Stream<String> getAuthorizedResourceIdentifiers(
287:       final EntityType ownerType,
288:       final String ownerId,
289:       final AuthorizationResourceType resourceType,
290:       final PermissionType permissionType) {
291:     final var authorizationOwnerType =
292:         switch (ownerType) {
293:           case GROUP -> AuthorizationOwnerType.GROUP;
294:           case ROLE -> AuthorizationOwnerType.ROLE;
295:           case USER -> AuthorizationOwnerType.USER;
296:           case MAPPING -> AuthorizationOwnerType.MAPPING;
297:           case CLIENT -> AuthorizationOwnerType.CLIENT;
298:           case UNSPECIFIED -> AuthorizationOwnerType.UNSPECIFIED;
299:         };
300: 
301:     final var direct =
302:         getDirectAuthorizedResourceIdentifiers(
303:             authorizationOwnerType, ownerId, resourceType, permissionType)
304:             .stream();
305:     final var viaRole =
306:         membershipState.getMemberships(ownerType, ownerId, RelationType.ROLE).stream()
307:             .flatMap(
308:                 roleId ->
309:                     getDirectAuthorizedResourceIdentifiers(
310:                         AuthorizationOwnerType.ROLE, roleId, resourceType, permissionType)
311:                         .stream());
312:     final var viaGroups =
313:         membershipState.getMemberships(ownerType, ownerId, RelationType.GROUP).stream()
314:             .<String>mapMulti(
315:                 (groupId, stream) -> {
316:                   getDirectAuthorizedResourceIdentifiers(
317:                           AuthorizationOwnerType.GROUP, groupId, resourceType, permissionType)
318:                       .forEach(stream);
319:                   membershipState
320:                       .getMemberships(EntityType.GROUP, groupId, RelationType.ROLE)
321:                       .stream()
322:                       .flatMap(
323:                           roleId ->
324:                               getDirectAuthorizedResourceIdentifiers(
325:                                   AuthorizationOwnerType.ROLE, roleId, resourceType, permissionType)
326:                                   .stream())
327:                       .forEach(stream);
328:                 });
329:     return Stream.concat(direct, Stream.concat(viaRole, viaGroups));
330:   }
