332:   /**
333:    * Checks if a user is assigned to a specific tenant. If multi-tenancy is disabled, this method
334:    * will always return true. If a command is written by Zeebe internally, it will also always
335:    * return true.
336:    *
337:    * @param command The command send by the user
338:    * @param tenantId The tenant we want to check assignment for
339:    * @return true if assigned, false otherwise
340:    */
341:   public boolean isAssignedToTenant(final TypedRecord<?> command, final String tenantId) {
342:     if (!multiTenancyEnabled) {
343:       return true;
344:     }
345: 
346:     if (!command.hasRequestMetadata()) {
347:       // The command is written by Zeebe internally. Internal Zeebe commands are always allowed to
348:       // access all tenants
349:       return true;
350:     }
351: 
352:     return getAuthorizedTenantIds(command).isAuthorizedForTenantId(tenantId);
353:   }
354: 
355:   public AuthorizedTenants getAuthorizedTenantIds(final TypedRecord<?> command) {
356:     if (isAuthorizedAnonymousUser(command)) {
357:       return AuthorizedTenants.ANONYMOUS;
358:     }
359: 
360:     final var username = getUsername(command);
361:     if (username.isPresent()) {
362:       final var tenantIds = getAuthorizedTenantIds(EntityType.USER, username.get()).toList();
363:       if (tenantIds.isEmpty()) {
364:         return AuthorizedTenants.DEFAULT_TENANTS;
365:       } else {
366:         return new AuthenticatedAuthorizedTenants(tenantIds);
367:       }
368:     }
369: 
370:     final var clientId = getClientId(command);
371:     if (clientId.isPresent()) {
372:       final var tenantIds = getAuthorizedTenantIds(EntityType.CLIENT, clientId.get()).toList();
373:       if (tenantIds.isEmpty()) {
374:         return AuthorizedTenants.DEFAULT_TENANTS;
375:       } else {
376:         return new AuthenticatedAuthorizedTenants(tenantIds);
377:       }
378:     }
379: 
380:     final var tenantsOfMapping =
381:         getPersistedMappings(command)
382:             .flatMap(mapping -> getAuthorizedTenantIds(EntityType.MAPPING, mapping.getMappingId()))
383:             .collect(Collectors.toSet());
384: 
385:     return tenantsOfMapping.isEmpty()
386:         ? AuthorizedTenants.DEFAULT_TENANTS
387:         : new AuthenticatedAuthorizedTenants(tenantsOfMapping);
388:   }
389: 
390:   private Stream<PersistedMapping> getPersistedMappings(final AuthorizationRequest request) {
391:     return getPersistedMappings(request.getCommand());
392:   }
