394:   private Stream<PersistedMapping> getPersistedMappings(final TypedRecord<?> command) {
395:     final var claims =
396:         (Map<String, Object>)
397:             command.getAuthorizations().getOrDefault(Authorization.USER_TOKEN_CLAIMS, Map.of());
398:     return MappingRuleMatcher.matchingRules(mappingState.getAll().stream(), claims);
399:   }
