32:   @Override
33:   public void applyState(final long key, final UserTaskRecord value) {
34:     userTaskState.updateUserTaskLifecycleState(key, LifecycleState.CANCELING);
35: 
36:     // Clean up data that may have been persisted by a previous transition
37:     variableState.removeVariableDocumentState(value.getElementInstanceKey());
38:     userTaskState.deleteIntermediateStateIfExists(key);
39:     userTaskState.deleteRecordRequestMetadata(key);
40:     resetTaskListenerIndices(value);
41: 
42:     // Persist new data related to "canceling" user task transition
43:     userTaskState.storeIntermediateState(value, LifecycleState.CANCELING);
44:     userTaskState.deleteInitialAssignee(key);
45:   }
46: 
47:   private void resetTaskListenerIndices(final UserTaskRecord record) {
48:     final long userTaskInstanceKey = record.getElementInstanceKey();
49:     final var userTaskInstance = elementInstanceState.getInstance(userTaskInstanceKey);
50: 
51:     if (userTaskInstance != null) {
52:       userTaskInstance.resetTaskListenerIndices();
53:       elementInstanceState.updateInstance(userTaskInstance);
54:     }
