266:         metadata -> {
267:           switch (metadata.getTriggerType()) {
268:             case USER_TASK -> responseWriter.writeRejection(
269:                 command.getKey(),
270:                 mapDeniedIntentToResponseIntent(intent),
271:                 command.getValue(),
272:                 command.getValueType(),
273:                 RejectionType.INVALID_STATE,
274:                 mapDeniedIntentToResponseRejectionReason(
275:                     intent,
276:                     persistedRecord.getUserTaskKey(),
277:                     command.getValue().getDeniedReason()),
278:                 metadata.getRequestId(),
279:                 metadata.getRequestStreamId());
