293:                         final var deniedReason =
294:                             USER_TASK_VARIABLE_UPDATE_REJECTION.formatted(
295:                                 userTaskInstanceKey, command.getValue().getDeniedReason());
296:                         responseWriter.writeRejection(
297:                             variableDocumentKey,
298:                             VariableDocumentIntent.UPDATE,
299:                             variableDocumentRecord,
300:                             ValueType.VARIABLE_DOCUMENT,
301:                             RejectionType.INVALID_STATE,
302:                             deniedReason,
