51:       "Assignment of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
52: 
53:   private static final String USER_TASK_UPDATE_REJECTION =
54:       "Update of the User Task with key '%d' was denied by Task Listener. Reason to deny: '%s'";
55: 
56:   private static final String USER_TASK_VARIABLE_UPDATE_REJECTION =
57:       "Variable update for user task instance with key '%d' was denied by Task Listener. Reason to deny: '%s'";
58: 
59:   private final UserTaskCommandProcessors commandProcessors;
60:   private final ProcessState processState;
61:   private final MutableUserTaskState userTaskState;
62:   private final ElementInstanceState elementInstanceState;
63:   private final VariableState variableState;
64: 
65:   private final BpmnJobBehavior jobBehavior;
66: 
67:   private final TypedRejectionWriter rejectionWriter;
68:   private final TypedResponseWriter responseWriter;
69:   private final StateWriter stateWriter;
70: 
71:   public UserTaskProcessor(
72:       final ProcessingState state,
73:       final MutableUserTaskState userTaskState,
74:       final KeyGenerator keyGenerator,
75:       final BpmnBehaviors bpmnBehaviors,
76:       final Writers writers,
77:       final AuthorizationCheckBehavior authCheckBehavior) {
78:     commandProcessors =
79:         new UserTaskCommandProcessors(
80:             state, keyGenerator, bpmnBehaviors, writers, authCheckBehavior);
81:     processState = state.getProcessState();
82:     this.userTaskState = userTaskState;
83:     elementInstanceState = state.getElementInstanceState();
84:     variableState = state.getVariableState();
85: 
86:     jobBehavior = bpmnBehaviors.jobBehavior();
87: 
88:     rejectionWriter = writers.rejection();
89:     responseWriter = writers.response();
90:     stateWriter = writers.state();
91:   }
92: 
93:   @Override
94:   public void processRecord(final TypedRecord<UserTaskRecord> command) {
95:     final UserTaskIntent intent = (UserTaskIntent) command.getIntent();
96:     switch (intent) {
97:       case CREATE, ASSIGN, CLAIM, UPDATE, COMPLETE, CANCEL ->
98:           processOperationCommand(command, intent);
99:       case COMPLETE_TASK_LISTENER -> processCompleteTaskListener(command);
100:       case DENY_TASK_LISTENER -> processDenyTaskListener(command);
101:       default -> throw new UnsupportedOperationException("Unexpected user task intent: " + intent);
102:     }
103:   }
104: 
105:   private void processCompleteTaskListener(final TypedRecord<UserTaskRecord> command) {
106:     final var lifecycleState = userTaskState.getLifecycleState(command.getKey());
107:     final var listenerEventType = mapLifecycleStateToEventType(lifecycleState);
108:     // we need to copy the intermediate user task record as we have read it from the state, and we
109:     // will read from the state again later, which in turn would modify this record
110:     final var intermediateUserTaskRecord =
111:         userTaskState.getIntermediateState(command.getKey()).getRecord().copy();
112:     final var userTaskElement = getUserTaskElement(intermediateUserTaskRecord);
113:     final var userTaskElementInstance = getUserTaskElementInstance(intermediateUserTaskRecord);
114:     final var context = buildContext(userTaskElementInstance);
115: 
116:     if (command.getValue().hasChangedAttributes()) {
117:       intermediateUserTaskRecord.wrapChangedAttributesIfValueChanged(command.getValue());
118: 
119:       if (intermediateUserTaskRecord.hasChangedAttributes()) {
120:         stateWriter.appendFollowUpEvent(
121:             command.getKey(), UserTaskIntent.CORRECTED, intermediateUserTaskRecord);
122:       }
123:     }
124: 
125:     findNextTaskListener(listenerEventType, userTaskElement, userTaskElementInstance)
126:         .ifPresentOrElse(
127:             listener -> {
128:               final var currentUserTask = userTaskState.getUserTask(command.getKey());
129:               final var changedAttributes =
130:                   intermediateUserTaskRecord.determineChangedAttributes(currentUserTask);
131:               jobBehavior.createNewTaskListenerJob(
132:                   context, intermediateUserTaskRecord, listener, changedAttributes);
133:             },
134:             () -> finalizeCommand(command, lifecycleState, intermediateUserTaskRecord));
135:   }
136: 
137:   private void finalizeCommand(
138:       final TypedRecord<UserTaskRecord> command,
139:       final LifecycleState lifecycleState,
140:       final UserTaskRecord userTaskRecord) {
141:     final var currentUserTask = userTaskState.getUserTask(command.getKey());
142:     userTaskRecord.setDiffAsChangedAttributes(currentUserTask);
143: 
144:     final var commandProcessor = determineProcessorFromUserTaskLifecycleState(lifecycleState);
145:     commandProcessor.onFinalizeCommand(command, userTaskRecord);
146:   }
147: 
148:   private void processDenyTaskListener(final TypedRecord<UserTaskRecord> command) {
149:     final var lifecycleState = userTaskState.getLifecycleState(command.getKey());
150:     final var persistedRecord = userTaskState.getUserTask(command.getKey());
151: 
152:     switch (lifecycleState) {
153:       case COMPLETING ->
154:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.COMPLETION_DENIED);
155:       case ASSIGNING, CLAIMING ->
156:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.ASSIGNMENT_DENIED);
157:       case UPDATING ->
158:           writeRejectionForCommand(command, persistedRecord, UserTaskIntent.UPDATE_DENIED);
159:       default -> throw new IllegalArgumentException(
160:           "Expected to reject operation for user task: '%d', but operation could not be determined from the task's current lifecycle state: '%s'"
161:               .formatted(command.getValue().getUserTaskKey(), lifecycleState));
162:     }
163:   }
164: 
165:   private void processOperationCommand(
166:       final TypedRecord<UserTaskRecord> command, final UserTaskIntent intent) {
167:     final var commandProcessor = commandProcessors.getCommandProcessor(intent);
168: 
169:     if (isRetriedCommand(command)) {
170:       // Skip `validateCommand` and `onCommand` invocations for retried command,
171:       // as it was already validated during the original execution
172:       finalizeCommandOrCreateTaskListenerJob(commandProcessor, command, command.getValue(), intent);
173:     } else {
174:       commandProcessor
175:           .validateCommand(command)
176:           // Create a modifiable copy of the persisted user task record, as `onCommand` may
177:           // apply the changed attributes from the command on top of persisted instance.
178:           .map(UserTaskRecord::copy)
179:           .thenDo(persistedRecord -> commandProcessor.onCommand(command, persistedRecord))
180:           .ifRightOrLeft(
181:               persistedRecord ->
182:                   finalizeCommandOrCreateTaskListenerJob(
183:                       commandProcessor, command, persistedRecord, intent),
184:               rejection -> handleCommandRejection(command, rejection));
185:     }
186:   }
187: 
188:   private void finalizeCommandOrCreateTaskListenerJob(
189:       final UserTaskCommandProcessor processor,
190:       final TypedRecord<UserTaskRecord> command,
191:       final UserTaskRecord persistedRecord,
192:       final UserTaskIntent intent) {
193: 
194:     final var userTaskElement = getUserTaskElement(persistedRecord);
195:     final var eventType = mapIntentToEventType(intent);
196: 
197:     if (userTaskElement.hasTaskListeners(eventType)) {
198:       /*
199:        * Store the original command's metadata (requestId, requestStreamId) before creating
200:        * the first task listener job. This metadata will be used later to finalize the original
201:        * command after all task listeners have been processed, ensuring that the engine can respond
202:        * appropriately to the original command request.
203:        *
204:        * Note:
205:        * Typically, persistence logic should be handled via `*Applier` classes. However, since
206:        * this involves request-related data, so in the case of command reconstruction,
207:        * we will have new request values anyway, so persisting these data here is acceptable.
208:        * A similar approach has been used in `ProcessInstanceCreationCreateWithResultProcessor`.
209:        */
210:       storeUserTaskRecordRequestMetadata(command);
211: 
212:       final var listener = userTaskElement.getTaskListeners(eventType).getFirst();
213:       final var userTaskElementInstance = getUserTaskElementInstance(persistedRecord);
214:       final var context = buildContext(userTaskElementInstance);
215:       jobBehavior.createNewTaskListenerJob(
216:           context, persistedRecord, listener, persistedRecord.getChangedAttributes());
217:     } else {
218:       processor.onFinalizeCommand(command, persistedRecord);
219:     }
220:   }
221: 
222:   private boolean isRetriedCommand(final TypedRecord<UserTaskRecord> command) {
223:     return command instanceof RetryTypedRecord<UserTaskRecord>;
224:   }
225: 
226:   private void storeUserTaskRecordRequestMetadata(final TypedRecord<UserTaskRecord> command) {
227:     if (!command.hasRequestMetadata()) {
228:       return;
229:     }
230: 
231:     final var metadata =
232:         new UserTaskTransitionTriggerRequestMetadata()
233:             .setIntent(command.getIntent())
234:             .setTriggerType(ValueType.USER_TASK)
235:             .setRequestId(command.getRequestId())
236:             .setRequestStreamId(command.getRequestStreamId());
237:     userTaskState.storeRecordRequestMetadata(command.getValue().getUserTaskKey(), metadata);
238:   }
239: 
240:   private void handleCommandRejection(
241:       final TypedRecord<UserTaskRecord> command, final Rejection rejection) {
242:     rejectionWriter.appendRejection(command, rejection.type(), rejection.reason());
243:     responseWriter.writeRejectionOnCommand(command, rejection.type(), rejection.reason());
244:   }
245: 
246:   private Optional<TaskListener> findNextTaskListener(
247:       final ZeebeTaskListenerEventType eventType,
248:       final ExecutableUserTask userTask,
249:       final ElementInstance userTaskElementInstance) {
250:     final var listeners = userTask.getTaskListeners(eventType);
251:     final int currentListenerIndex = userTaskElementInstance.getTaskListenerIndex(eventType);
252:     return listeners.stream().skip(currentListenerIndex).findFirst();
253:   }
254: 
255:   private void writeRejectionForCommand(
256:       final TypedRecord<UserTaskRecord> command,
257:       final UserTaskRecord persistedRecord,
258:       final UserTaskIntent intent) {
259: 
260:     persistedRecord.setDeniedReason(command.getValue().getDeniedReason());
261:     final var recordRequestMetadata =
262:         userTaskState.findRecordRequestMetadata(persistedRecord.getUserTaskKey());
263: 
264:     stateWriter.appendFollowUpEvent(persistedRecord.getUserTaskKey(), intent, persistedRecord);
265:     recordRequestMetadata.ifPresent(
266:         metadata -> {
267:           switch (metadata.getValueType()) {
268:             case USER_TASK -> responseWriter.writeRejection(
269:                 command.getKey(),
270:                 mapDeniedIntentToResponseIntent(intent),
271:                 command.getValue(),
272:                 command.getValueType(),
273:                 RejectionType.INVALID_STATE,
274:                 mapDeniedIntentToResponseRejectionReason(
275:                     intent,
276:                     persistedRecord.getUserTaskKey(),
277:                     command.getValue().getDeniedReason()),
278:                 metadata.getRequestId(),
279:                 metadata.getRequestStreamId());
280:             case VARIABLE_DOCUMENT -> {
281:               final long userTaskInstanceKey = command.getValue().getElementInstanceKey();
282:               variableState
283:                   .findVariableDocumentState(userTaskInstanceKey)
284:                   .ifPresent(
285:                       variableDocumentState -> {
286:                         final long variableDocumentKey = variableDocumentState.getKey();
287:                         final var variableDocumentRecord = variableDocumentState.getRecord();
288:                         stateWriter.appendFollowUpEvent(
289:                             variableDocumentKey,
290:                             VariableDocumentIntent.UPDATE_DENIED,
291:                             variableDocumentRecord);
292: 
293:                         final var deniedReason =
294:                             USER_TASK_VARIABLE_UPDATE_REJECTION.formatted(
295:                                 userTaskInstanceKey, command.getValue().getDeniedReason());
296:                         responseWriter.writeRejection(
297:                             variableDocumentKey,
298:                             VariableDocumentIntent.UPDATE,
299:                             variableDocumentRecord,
300:                             ValueType.VARIABLE_DOCUMENT,
301:                             RejectionType.INVALID_STATE,
302:                             deniedReason,
303:                             metadata.getRequestId(),
304:                             metadata.getRequestStreamId());
305:                       });
306:             }
307:             default -> throw new IllegalArgumentException(
308:                 "Unexpected user task transition trigger type: '%s'"
309:                     .formatted(metadata.getValueType()));
310:           }
311:         });
312:   }
313: 
314:   private ExecutableUserTask getUserTaskElement(final UserTaskRecord userTaskRecord) {
315:     return processState.getFlowElement(
316:         userTaskRecord.getProcessDefinitionKey(),
317:         userTaskRecord.getTenantId(),
318:         userTaskRecord.getElementIdBuffer(),
319:         ExecutableUserTask.class);
320:   }
321: 
322:   private ZeebeTaskListenerEventType mapIntentToEventType(final UserTaskIntent intent) {
323:     return switch (intent) {
324:       case CREATE -> ZeebeTaskListenerEventType.creating;
325:       case ASSIGN, CLAIM -> ZeebeTaskListenerEventType.assigning;
326:       case UPDATE -> ZeebeTaskListenerEventType.updating;
327:       case COMPLETE -> ZeebeTaskListenerEventType.completing;
328:       case CANCEL -> ZeebeTaskListenerEventType.canceling;
329:       default ->
330:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
331:     };
332:   }
333: 
334:   private ZeebeTaskListenerEventType mapLifecycleStateToEventType(
335:       final LifecycleState lifecycleState) {
336:     return switch (lifecycleState) {
337:       case CREATING -> ZeebeTaskListenerEventType.creating;
338:       case ASSIGNING, CLAIMING -> ZeebeTaskListenerEventType.assigning;
339:       case UPDATING -> ZeebeTaskListenerEventType.updating;
340:       case COMPLETING -> ZeebeTaskListenerEventType.completing;
341:       case CANCELING -> ZeebeTaskListenerEventType.canceling;
342:       default -> throw new IllegalArgumentException(
343:           "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
344:     };
345:   }
346: 
347:   private UserTaskIntent mapDeniedIntentToResponseIntent(final UserTaskIntent intent) {
348:     return switch (intent) {
349:       case COMPLETION_DENIED -> UserTaskIntent.COMPLETE;
350:       case ASSIGNMENT_DENIED -> UserTaskIntent.ASSIGN;
351:       case UPDATE_DENIED -> UserTaskIntent.UPDATE;
352:       default ->
353:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
354:     };
355:   }
356: 
357:   private String mapDeniedIntentToResponseRejectionReason(
358:       final UserTaskIntent intent, final long userTaskKey, final String deniedReason) {
359:     return switch (intent) {
360:       case COMPLETION_DENIED -> USER_TASK_COMPLETION_REJECTION.formatted(userTaskKey, deniedReason);
361:       case ASSIGNMENT_DENIED -> USER_TASK_ASSIGNMENT_REJECTION.formatted(userTaskKey, deniedReason);
362:       case UPDATE_DENIED -> USER_TASK_UPDATE_REJECTION.formatted(userTaskKey, deniedReason);
363:       default ->
364:           throw new IllegalArgumentException("Unexpected user task intent: '%s'".formatted(intent));
365:     };
366:   }
367: 
368:   private UserTaskCommandProcessor determineProcessorFromUserTaskLifecycleState(
369:       final LifecycleState lifecycleState) {
370: 
371:     final var userTaskIntent =
372:         switch (lifecycleState) {
373:           case CREATING -> UserTaskIntent.CREATE;
374:           case ASSIGNING -> UserTaskIntent.ASSIGN;
375:           case CLAIMING -> UserTaskIntent.CLAIM;
376:           case UPDATING -> UserTaskIntent.UPDATE;
377:           case COMPLETING -> UserTaskIntent.COMPLETE;
378:           case CANCELING -> UserTaskIntent.CANCEL;
379:           default -> throw new IllegalArgumentException(
380:               "Unexpected user task lifecycle state: '%s'".formatted(lifecycleState));
381:         };
382: 
383:     return commandProcessors.getCommandProcessor(userTaskIntent);
384:   }
385: 
386:   private ElementInstance getUserTaskElementInstance(final UserTaskRecord userTaskRecord) {
387:     final var elementInstanceKey = userTaskRecord.getElementInstanceKey();
388:     return elementInstanceState.getInstance(elementInstanceKey);
389:   }
390: 
391:   private BpmnElementContext buildContext(final ElementInstance elementInstance) {
392:     final var context = new BpmnElementContextImpl();
393:     context.init(elementInstance.getKey(), elementInstance.getValue(), elementInstance.getState());
394:     return context;
395:   }
396: }
