49:       "Expected to trigger update transition for user task with key '%d', but it is in state '%s'";
50: 
51:   private final ElementInstanceState elementInstanceState;
52:   private final MutableUserTaskState userTaskState;
53:   private final ProcessState processState;
54:   private final KeyGenerator keyGenerator;
55:   private final VariableBehavior variableBehavior;
56:   private final BpmnJobBehavior jobBehavior;
57:   private final Writers writers;
58:   private final AuthorizationCheckBehavior authCheckBehavior;
59: 
60:   public VariableDocumentUpdateProcessor(
61:       final ProcessingState processingState,
62:       final KeyGenerator keyGenerator,
63:       final BpmnBehaviors bpmnBehaviors,
64:       final Writers writers,
65:       final MutableUserTaskState userTaskState,
66:       final AuthorizationCheckBehavior authCheckBehavior) {
67:     this.elementInstanceState = processingState.getElementInstanceState();
68:     this.userTaskState = userTaskState;
69:     this.processState = processingState.getProcessState();
70:     this.keyGenerator = keyGenerator;
71:     this.variableBehavior = bpmnBehaviors.variableBehavior();
72:     this.jobBehavior = bpmnBehaviors.jobBehavior();
73:     this.writers = writers;
74:     this.authCheckBehavior = authCheckBehavior;
75:   }
76: 
77:   @Override
78:   public void processRecord(final TypedRecord<VariableDocumentRecord> record) {
79:     final VariableDocumentRecord value = record.getValue();
80: 
81:     final ElementInstance scope = elementInstanceState.getInstance(value.getScopeKey());
82:     if (scope == null || scope.isTerminating() || scope.isInFinalState()) {
83:       final String reason = String.format(ERROR_MESSAGE_SCOPE_NOT_FOUND, value.getScopeKey());
84:       writers.rejection().appendRejection(record, RejectionType.NOT_FOUND, reason);
85:       writers.response().writeRejectionOnCommand(record, RejectionType.NOT_FOUND, reason);
86:       return;
87:     }
88: 
89:     final var authRequest =
90:         new AuthorizationRequest(
91:                 record,
92:                 AuthorizationResourceType.PROCESS_DEFINITION,
93:                 PermissionType.UPDATE_PROCESS_INSTANCE,
94:                 scope.getValue().getTenantId())
95:             .addResourceId(scope.getValue().getBpmnProcessId());
96:     final var isAuthorized = authCheckBehavior.isAuthorized(authRequest);
97:     if (isAuthorized.isLeft()) {
98:       final var rejection = isAuthorized.getLeft();
99:       final String errorMessage =
100:           RejectionType.NOT_FOUND.equals(rejection.type())
101:               ? AuthorizationCheckBehavior.NOT_FOUND_ERROR_MESSAGE.formatted(
102:                   "update variables for element",
103:                   scope.getValue().getProcessInstanceKey(),
104:                   "such element")
105:               : rejection.reason();
106:       writers.rejection().appendRejection(record, rejection.type(), errorMessage);
107:       writers.response().writeRejectionOnCommand(record, rejection.type(), errorMessage);
108:       return;
109:     }
110: 
111:     final String tenantId = scope.getValue().getTenantId();
112: 
113:     if (isCamundaUserTask(scope)) {
114:       final long userTaskKey = scope.getUserTaskKey();
115:       final var lifecycleState = userTaskState.getLifecycleState(userTaskKey);
116:       if (lifecycleState != LifecycleState.CREATED) {
117:         final var reason = INVALID_USER_TASK_STATE_MESSAGE.formatted(userTaskKey, lifecycleState);
118:         writers.rejection().appendRejection(record, RejectionType.INVALID_STATE, reason);
119:         writers.response().writeRejectionOnCommand(record, RejectionType.INVALID_STATE, reason);
120:         return;
121:       }
122: 
123:       final long key = keyGenerator.nextKey();
124:       writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATING, value);
125: 
126:       final var userTaskRecord = userTaskState.getUserTask(userTaskKey);
127:       if (hasVariables(value)) {
128:         userTaskRecord.setVariables(value.getVariablesBuffer()).setVariablesChanged();
129:       }
130:       writers.state().appendFollowUpEvent(userTaskKey, UserTaskIntent.UPDATING, userTaskRecord);
131: 
132:       final var userTaskElement =
133:           processState.getFlowElement(
134:               userTaskRecord.getProcessDefinitionKey(),
135:               tenantId,
136:               userTaskRecord.getElementIdBuffer(),
137:               ExecutableUserTask.class);
138: 
139:       if (userTaskElement.hasTaskListeners(ZeebeTaskListenerEventType.updating)) {
140:         storeRecordRequestMetadata(userTaskKey, record);
141: 
142:         final var listener =
143:             userTaskElement.getTaskListeners(ZeebeTaskListenerEventType.updating).getFirst();
144:         jobBehavior.createNewTaskListenerJob(
145:             buildContext(scope), userTaskRecord, listener, userTaskRecord.getChangedAttributes());
146:         return;
147:       }
148: 
149:       switch (value.getUpdateSemantics()) {
150:         case LOCAL ->
151:             variableBehavior.mergeLocalDocument(
152:                 userTaskRecord.getElementInstanceKey(),
153:                 userTaskRecord.getProcessDefinitionKey(),
154:                 userTaskRecord.getProcessInstanceKey(),
155:                 userTaskRecord.getBpmnProcessIdBuffer(),
156:                 userTaskRecord.getTenantId(),
157:                 value.getVariablesBuffer());
158:         case PROPAGATE ->
159:             variableBehavior.mergeDocument(
160:                 userTaskRecord.getElementInstanceKey(),
161:                 userTaskRecord.getProcessDefinitionKey(),
162:                 userTaskRecord.getProcessInstanceKey(),
163:                 userTaskRecord.getBpmnProcessIdBuffer(),
164:                 userTaskRecord.getTenantId(),
165:                 value.getVariablesBuffer());
166:         default ->
167:             throw new IllegalStateException(
168:                 "Unexpected variable update semantic: '%s'. Expected either 'LOCAL' or 'PROPAGATE'."
169:                     .formatted(value.getUpdateSemantics()));
170:       }
171: 
172:       writers
173:           .state()
174:           .appendFollowUpEvent(scope.getUserTaskKey(), UserTaskIntent.UPDATED, userTaskRecord);
175: 
176:       writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATED, value);
177:       writers.response().writeEventOnCommand(key, VariableDocumentIntent.UPDATED, value, record);
178:       return;
179:     }
180: 
181:     final long processDefinitionKey = scope.getValue().getProcessDefinitionKey();
182:     final long processInstanceKey = scope.getValue().getProcessInstanceKey();
183:     final DirectBuffer bpmnProcessId = scope.getValue().getBpmnProcessIdBuffer();
184:     try {
185:       if (value.getUpdateSemantics() == VariableDocumentUpdateSemantic.LOCAL) {
186:         variableBehavior.mergeLocalDocument(
187:             scope.getKey(),
188:             processDefinitionKey,
189:             processInstanceKey,
190:             bpmnProcessId,
191:             tenantId,
192:             value.getVariablesBuffer());
193:       } else {
194:         variableBehavior.mergeDocument(
195:             scope.getKey(),
196:             processDefinitionKey,
197:             processInstanceKey,
198:             bpmnProcessId,
199:             tenantId,
200:             value.getVariablesBuffer());
201:       }
202:     } catch (final MsgpackReaderException e) {
203:       final String reason =
204:           String.format(
205:               "Expected document to be valid msgpack, but it could not be read: '%s'",
206:               e.getMessage());
207:       writers.rejection().appendRejection(record, RejectionType.INVALID_ARGUMENT, reason);
208:       writers.response().writeRejectionOnCommand(record, RejectionType.INVALID_ARGUMENT, reason);
209:       return;
210:     }
211: 
212:     final long key = keyGenerator.nextKey();
213: 
214:     writers.state().appendFollowUpEvent(key, VariableDocumentIntent.UPDATED, value);
215:     writers.response().writeEventOnCommand(key, VariableDocumentIntent.UPDATED, value, record);
216:   }
217: 
218:   private static boolean hasVariables(final VariableDocumentRecord record) {
219:     return !DocumentValue.EMPTY_DOCUMENT.equals(record.getVariablesBuffer());
220:   }
221: 
222:   private static boolean isCamundaUserTask(ElementInstance elementInstance) {
223:     return elementInstance.getValue().getBpmnElementType() == BpmnElementType.USER_TASK
224:         && elementInstance.getUserTaskKey() > -1L;
225:   }
226: 
227:   private static BpmnElementContext buildContext(final ElementInstance elementInstance) {
228:     final var context = new BpmnElementContextImpl();
229:     context.init(elementInstance.getKey(), elementInstance.getValue(), elementInstance.getState());
230:     return context;
231:   }
232: 
233:   void storeRecordRequestMetadata(
234:       final long userTaskKey, final TypedRecord<VariableDocumentRecord> command) {
235:     if (!command.hasRequestMetadata()) {
236:       return;
237:     }
238: 
239:     final var metadata =
240:         new UserTaskTransitionTriggerRequestMetadata()
241:             .setIntent(command.getIntent())
242:             .setTriggerType(ValueType.VARIABLE_DOCUMENT)
243:             .setRequestId(command.getRequestId())
244:             .setRequestStreamId(command.getRequestStreamId());
245:     userTaskState.storeRecordRequestMetadata(userTaskKey, metadata);
246:   }
247: }
