165:   private void processOperationCommand(
166:       final TypedRecord<UserTaskRecord> command, final UserTaskIntent intent) {
167:     final var commandProcessor = commandProcessors.getCommandProcessor(intent);
168: 
169:     if (isRetriedCommand(command)) {
170:       // Skip `validateCommand` and `onCommand` invocations for retried command,
171:       // as it was already validated during the original execution
172:       finalizeCommandOrCreateTaskListenerJob(commandProcessor, command, command.getValue(), intent);
173:     } else {
174:       commandProcessor
175:           .validateCommand(command)
176:           // Create a modifiable copy of the persisted user task record, as `onCommand` may
177:           // apply the changed attributes from the command on top of persisted instance.
178:           .map(UserTaskRecord::copy)
179:           .thenDo(persistedRecord -> commandProcessor.onCommand(command, persistedRecord))
180:           .ifRightOrLeft(
181:               persistedRecord ->
182:                   finalizeCommandOrCreateTaskListenerJob(
183:                       commandProcessor, command, persistedRecord, intent),
184:               rejection -> handleCommandRejection(command, rejection));
185:     }
186:   }
