188:   private void finalizeCommandOrCreateTaskListenerJob(
189:       final UserTaskCommandProcessor processor,
190:       final TypedRecord<UserTaskRecord> command,
191:       final UserTaskRecord persistedRecord,
192:       final UserTaskIntent intent) {
193: 
194:     final var userTaskElement = getUserTaskElement(persistedRecord);
195:     final var eventType = mapIntentToEventType(intent);
196: 
197:     if (userTaskElement.hasTaskListeners(eventType)) {
198:       /*
199:        * Store the original command's metadata (requestId, requestStreamId) before creating
200:        * the first task listener job. This metadata will be used later to finalize the original
201:        * command after all task listeners have been processed, ensuring that the engine can respond
202:        * appropriately to the original command request.
203:        *
204:        * Note:
205:        * Typically, persistence logic should be handled via `*Applier` classes. However, since
206:        * this involves request-related data, so in the case of command reconstruction,
207:        * we will have new request values anyway, so persisting these data here is acceptable.
208:        * A similar approach has been used in `ProcessInstanceCreationCreateWithResultProcessor`.
209:        */
210:       storeUserTaskRecordRequestMetadata(command);
211: 
212:       final var listener = userTaskElement.getTaskListeners(eventType).getFirst();
213:       final var userTaskElementInstance = getUserTaskElementInstance(persistedRecord);
214:       final var context = buildContext(userTaskElementInstance);
215:       jobBehavior.createNewTaskListenerJob(
216:           context, persistedRecord, listener, persistedRecord.getChangedAttributes());
217:     } else {
218:       processor.onFinalizeCommand(command, persistedRecord);
219:     }
220:   }
