222:   private boolean isRetriedCommand(final TypedRecord<UserTaskRecord> command) {
223:     return command instanceof RetryTypedRecord<UserTaskRecord>;
224:   }
225: 
226:   private void storeUserTaskRecordRequestMetadata(final TypedRecord<UserTaskRecord> command) {
227:     if (!command.hasRequestMetadata()) {
228:       return;
229:     }
230: 
231:     final var metadata =
232:         new UserTaskTransitionTriggerRequestMetadata()
233:             .setIntent(command.getIntent())
234:             .setValueType(ValueType.USER_TASK)
235:             .setRequestId(command.getRequestId())
236:             .setRequestStreamId(command.getRequestStreamId());
237:     userTaskState.storeRecordRequestMetadata(command.getValue().getUserTaskKey(), metadata);
238:   }
