240:   private void handleCommandRejection(
241:       final TypedRecord<UserTaskRecord> command, final Rejection rejection) {
242:     rejectionWriter.appendRejection(command, rejection.type(), rejection.reason());
243:     responseWriter.writeRejectionOnCommand(command, rejection.type(), rejection.reason());
244:   }
