247:       final ZeebeTaskListenerEventType eventType,
248:       final ExecutableUserTask userTask,
249:       final ElementInstance userTaskElementInstance) {
250:     final var listeners = userTask.getTaskListeners(eventType);
251:     final int currentListenerIndex = userTaskElementInstance.getTaskListenerIndex(eventType);
252:     return listeners.stream().skip(currentListenerIndex).findFirst();
253:   }
