322:   private ZeebeTaskListenerEventType mapIntentToEventType(final UserTaskIntent intent) {
323:     return switch (intent) {
324:       case CREATE -> ZeebeTaskListenerEventType.creating;
325:       case ASSIGN, CLAIM -> ZeebeTaskListenerEventType.assigning;
326:       case UPDATE -> ZeebeTaskListenerEventType.updating;
