339:       case UPDATING -> ZeebeTaskListenerEventType.updating;
340:       case COMPLETING -> ZeebeTaskListenerEventType.completing;
341:       case CANCELING -> ZeebeTaskListenerEventType.canceling;
342:       default -> throw new IllegalArgumentException(
