371:     final var userTaskIntent =
372:         switch (lifecycleState) {
373:           case CREATING -> UserTaskIntent.CREATE;
374:           case ASSIGNING -> UserTaskIntent.ASSIGN;
375:           case CLAIMING -> UserTaskIntent.CLAIM;
376:           case UPDATING -> UserTaskIntent.UPDATE;
