1501:   private static Either<List<String>, List<VariableValueFilter>> toVariableValueFilters(
1502:       final List<VariableValueFilterRequest> filters) {
1503:     if (CollectionUtils.isEmpty(filters)) {
1504:       return Either.right(List.of());
1505:     }
1506: 
1507:     final List<String> validationErrors = new ArrayList<>();
1508:     final List<VariableValueFilter> variableValueFilters =
1509:         filters.stream()
1510:             .flatMap(
1511:                 filter -> {
1512:                   if (filter.getName() == null) {
1513:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_NAME);
1514:                   }
1515:                   if (filter.getValue() == null
1516:                       || filter.getValue().equals(EMPTY_ADVANCED_STRING_FILTER)
1517:                       || filter.getValue().equals(EMPTY_BASIC_STRING_FILTER)) {
1518:                     validationErrors.add(ERROR_MESSAGE_NULL_VARIABLE_VALUE);
1519:                   }
1520:                   // if there is no validation error overall, process the filter
1521:                   return validationErrors.isEmpty()
1522:                       ? toVariableValueFilters(filter.getName(), filter.getValue()).stream()
1523:                       : Stream.empty();
