175:   public static Either<List<String>, ProcessDefinitionStatisticsFilter>
176:   toProcessDefinitionStatisticsFilter(
177:       final long processDefinitionKey,
178:       final io.camunda.zeebe.gateway.protocol.rest.ProcessDefinitionStatisticsFilter filter) {
179:     final List<String> validationErrors = new ArrayList<>();
180: 
181:     final Either<List<String>, ProcessDefinitionStatisticsFilter.Builder> builder =
182:         toBaseProcessInstanceFilterFields(processDefinitionKey, filter);
183:     if (builder.isLeft()) {
184:       validationErrors.addAll(builder.getLeft());
185:     }
186: 
187:     if (filter != null) {
188:       if (filter.get$Or() != null && !filter.get$Or().isEmpty()) {
189:         for (final BaseProcessInstanceFilterFields or : filter.get$Or()) {
190:           final var orBuilder = toBaseProcessInstanceFilterFields(processDefinitionKey, or);
191:           if (orBuilder.isLeft()) {
192:             validationErrors.addAll(orBuilder.getLeft());
193:           } else {
194:             builder.get().addOrOperation(orBuilder.get().build());
195:           }
196:         }
197:       }
198:     }
199: 
200:     return validationErrors.isEmpty()
201:         ? Either.right(builder.get().build())
202:         : Either.left(validationErrors);
203:   }
