1614:       F extends FilterBase,
1615:       S extends SortOption>
1616:   Either<ProblemDetail, T> buildSearchQuery(
1617:       final Either<List<String>, F> filter,
1618:       final Either<List<String>, S> sorting,
1619:       final Either<List<String>, SearchQueryPage> page,
1620:       final Supplier<B> queryBuilderSupplier) {
1621:     final List<String> validationErrors = new ArrayList<>();
1622:     if (filter.isLeft()) {
1623:       validationErrors.addAll(filter.getLeft());
1624:     }
1625:     if (sorting.isLeft()) {
1626:       validationErrors.addAll(sorting.getLeft());
1627:     }
1628:     if (page.isLeft()) {
1629:       validationErrors.addAll(page.getLeft());
1630:     }
1631: 
1632:     return getResult(
1633:         RequestValidator.createProblemDetail(validationErrors),
1634:         () ->
1635:             queryBuilderSupplier
1636:                 .get()
1637:                 .page(page.get())
1638:                 .filter(filter.get())
1639:                 .sort(sorting.get())
1640:                 .build());
