1668:   private static DateValueFilter toDateValueFilter(final String after, final String before) {
1669:     final Optional<OffsetDateTime> beforeDateTime = ofNullable(before).map(OffsetDateTime::parse);
1670:     final Optional<OffsetDateTime> afterDateTime =
1671:         Optional.ofNullable(after).map(OffsetDateTime::parse);
1672:     if (beforeDateTime.isEmpty() && afterDateTime.isEmpty()) {
1673:       return null;
1674:     }
1675:     return new DateValueFilter.Builder()
1676:         .before(beforeDateTime.orElse(null))
1677:         .after(afterDateTime.orElse(null))
1678:         .build();
