535:         case DECISION_INSTANCE_ID -> builder.decisionInstanceId();
536:         case STATE -> builder.state();
537:         case EVALUATION_DATE -> builder.evaluationDate();
538:         case EVALUATION_FAILURE -> builder.evaluationFailure();
539:         case PROCESS_DEFINITION_KEY -> builder.processDefinitionKey();
540:         case PROCESS_INSTANCE_KEY -> builder.processInstanceKey();
541:         case DECISION_DEFINITION_KEY -> builder.decisionDefinitionKey();
542:         case DECISION_DEFINITION_ID -> builder.decisionDefinitionId();
543:         case DECISION_DEFINITION_NAME -> builder.decisionDefinitionName();
544:         case DECISION_DEFINITION_VERSION -> builder.decisionDefinitionVersion();
545:         case DECISION_DEFINITION_TYPE -> builder.decisionDefinitionType();
546:         case TENANT_ID -> builder.tenantId();
547:         default -> validationErrors.add(ERROR_UNKNOWN_SORT_BY.formatted(field));
548:       }
549:     }
550:     return validationErrors;
551:   }
