205:   private static Either<List<String>, ProcessDefinitionStatisticsFilter.Builder>
206:   toBaseProcessInstanceFilterFields(
207:       final long processDefinitionKey, final BaseProcessInstanceFilterFields filter) {
208:     final var builder = FilterBuilders.processDefinitionStatisticsFilter(processDefinitionKey);
209:     final List<String> validationErrors = new ArrayList<>();
210:     if (filter != null) {
211:       ofNullable(filter.getProcessInstanceKey())
212:           .map(mapToOperations(Long.class))
213:           .ifPresent(builder::processInstanceKeyOperations);
214:       ofNullable(filter.getParentProcessInstanceKey())
215:           .map(mapToOperations(Long.class))
216:           .ifPresent(builder::parentProcessInstanceKeyOperations);
217:       ofNullable(filter.getParentElementInstanceKey())
218:           .map(mapToOperations(Long.class))
219:           .ifPresent(builder::parentFlowNodeInstanceKeyOperations);
220:       ofNullable(filter.getStartDate())
221:           .map(mapToOperations(OffsetDateTime.class))
222:           .ifPresent(builder::startDateOperations);
223:       ofNullable(filter.getEndDate())
224:           .map(mapToOperations(OffsetDateTime.class))
225:           .ifPresent(builder::endDateOperations);
226:       ofNullable(filter.getState())
227:           .map(mapToOperations(String.class, new ProcessInstanceStateConverter()))
228:           .ifPresent(builder::stateOperations);
229:       ofNullable(filter.getHasIncident()).ifPresent(builder::hasIncident);
230:       ofNullable(filter.getTenantId())
231:           .map(mapToOperations(String.class))
232:           .ifPresent(builder::tenantIdOperations);
233:       ofNullable(filter.getBatchOperationId())
234:           .map(mapToOperations(String.class))
235:           .ifPresent(builder::batchOperationIdOperations);
236:       ofNullable(filter.getErrorMessage())
237:           .map(mapToOperations(String.class))
238:           .ifPresent(builder::errorMessageOperations);
239:       ofNullable(filter.getHasRetriesLeft()).ifPresent(builder::hasRetriesLeft);
240:       ofNullable(filter.getElementId())
241:           .map(mapToOperations(String.class))
242:           .ifPresent(builder::flowNodeIdOperations);
243:       ofNullable(filter.getHasElementInstanceIncident())
244:           .ifPresent(builder::hasFlowNodeInstanceIncident);
245:       ofNullable(filter.getElementInstanceState())
246:           .map(mapToOperations(String.class))
247:           .ifPresent(builder::flowNodeInstanceStateOperations);
248:       ofNullable(filter.getIncidentErrorHashCode()).ifPresent(builder::incidentErrorHashCodes);
249:       if (!CollectionUtils.isEmpty(filter.getVariables())) {
250:         final Either<List<String>, List<VariableValueFilter>> either =
251:             toVariableValueFilters(filter.getVariables());
252:         if (either.isLeft()) {
253:           validationErrors.addAll(either.getLeft());
254:         } else {
255:           builder.variables(either.get());
256:         }
257:       }
258:     }
259:     return validationErrors.isEmpty() ? Either.right(builder) : Either.left(validationErrors);
260:   }
