1540:   private static Either<List<String>, SearchQueryPage> toSearchQueryPage(
1541:       final SearchQueryPageRequest requestedPage) {
1542:     if (requestedPage == null) {
1543:       return Either.right(null);
1544:     }
1545: 
1546:     final Object[] searchAfter = toArrayOrNull(requestedPage.getSearchAfter());
1547:     final Object[] searchBefore = toArrayOrNull(requestedPage.getSearchBefore());
1548: 
1549:     if (searchAfter != null && searchBefore != null) {
1550:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER));
1551:     }
1552:     if (requestedPage.getFrom() != null && (searchAfter != null || searchBefore != null)) {
1553:       return Either.left(List.of(ERROR_SEARCH_BEFORE_AND_AFTER_AND_FROM));
1554:     }
1555: 
1556:     return Either.right(
1557:         SearchQueryPage.of(
1558:             (p) ->
1559:                 p.size(requestedPage.getLimit())
1560:                     .from(requestedPage.getFrom())
1561:                     .searchAfter(searchAfter)
1562:                     .searchBefore(searchBefore)));
1563:   }
