1565:   private static <T, B extends SortOption.AbstractBuilder<B> & ObjectBuilder<T>, F>
1566:   Either<List<String>, T> toSearchQuerySort(
1567:       final List<SearchQuerySortRequest<F>> sorting,
1568:       final Supplier<B> builderSupplier,
1569:       final BiFunction<F, B, List<String>> sortFieldMapper) {
1570:     if (sorting != null && !sorting.isEmpty()) {
1571:       final List<String> validationErrors = new ArrayList<>();
1572:       final var builder = builderSupplier.get();
1573:       for (final SearchQuerySortRequest<F> sort : sorting) {
1574:         validationErrors.addAll(sortFieldMapper.apply(sort.field(), builder));
1575:         applySortOrder(sort.order(), builder);
1576:       }
1577: 
1578:       return validationErrors.isEmpty()
1579:           ? Either.right(builder.build())
1580:           : Either.left(validationErrors);
1581:     }
1582: 
1583:     return Either.right(null);
1584:   }
