33: abstract class AbstractEntityReader<T> {
34: 
35:   private static final SearchColumn<?>[] EMPTY_SEARCHABLE_COLUMNS = new SearchColumn[0];
36:   private final Map<String, SearchColumn<T>> columns;
37: 
38:   public AbstractEntityReader(final SearchColumn<T>[] searchableColumns) {
39:     final var searchColumns =
40:         Objects.requireNonNullElse(searchableColumns, (SearchColumn<T>[]) EMPTY_SEARCHABLE_COLUMNS);
41: 
42:     columns =
43:         Stream.of(searchColumns)
44:             .collect(Collectors.toMap(SearchColumn::property, Function.identity()));
45:   }
46: 
47:   private SearchColumn<T> getSearchColumn(final String property) {
48:     return Optional.ofNullable(columns.get(property))
49:         .orElseThrow(() -> new IllegalArgumentException("Unknown sortField: " + property));
50:   }
51: 
52:   @SafeVarargs
53:   public final DbQuerySorting<T> convertSort(
54:       final SortOption sortOption, final SearchColumn<T>... discriminatorColumns) {
55:     final var builder = new DbQuerySorting.Builder<T>();
56:     final var discriminatorColumnList = new ArrayList<>(Arrays.asList(discriminatorColumns));
57: 
58:     for (final FieldSorting fieldSorting : sortOption.getFieldSortings()) {
59:       final var column = getSearchColumn(fieldSorting.field());
60: 
61:       // remove the column from the discriminator list to not sort double
62:       discriminatorColumnList.remove(column);
63:       builder.addEntry(column, fieldSorting.order());
64:     }
65: 
66:     for (final SearchColumn<T> discriminatorColumn : discriminatorColumnList) {
67:       builder.addEntry(discriminatorColumn, SortOrder.ASC);
68:     }
69: 
70:     return builder.build();
71:   }
72: 
73:   public DbQueryPage convertPaging(final DbQuerySorting<T> sort, final SearchQueryPage page) {
74:     List<KeySetPagination> keySetPagination = new ArrayList<>();
75:     if (page.searchAfter() != null || page.before() != null) {
76:       keySetPagination = createKeySetPagination(sort, page);
77:     }
78: 
79:     return new DbQueryPage(page.size(), page.from(), keySetPagination);
80:   }
81: 
82:   /**
83:    * To create key set pagination for rdbms, supporting mixed order (e.g. <code>ORDER BY name ASC,
84:    * startDate DESC, key ASC</code>), a simple solution like
85:    *
86:    * <pre>WHERE (name, startDate, key) < ("Process A", "2024-10-10T08:00:00Z", 1234)</pre>
87:    *
88:    * <br>
89:    * does not work anymore. <br>
90:    * <br>
91:    * Instead, we need to split up the query into multiple comparisons:
92:    *
93:    * <pre>
94:    * WHERE (name > "Process A")
95:    *    OR (name = "Process A" AND startDate < "2024-10-10T08:00:00Z")
96:    *    OR (name = "Process A" AND startDate = "2024-10-10T08:00:00Z" AND key > 1234)
97:    * </pre>
98:    *
99:    * This method takes the sortOrder and the sortValues (before or after) and creates a list grouped
100:    * expressions. We do this in Java and not in MyBatis because it is easier to program and to test
101:    */
102:   private List<KeySetPagination> createKeySetPagination(
103:       final DbQuerySorting<T> sort, final SearchQueryPage page) {
104:     final boolean isSearchAfter = page.searchAfter() != null;
105:     final var cursorValue = isSearchAfter ? page.searchAfter() : page.before();
106:     final Object[] sortValues = Cursor.decode(cursorValue, sort.columns());
107:     final List<KeySetPagination> keySetPagination = new ArrayList<>();
108: 
109:     for (int i = 0; i < sort.orderings().size(); i++) {
110:       final List<KeySetPaginationFieldEntry> fieldEntries = new ArrayList<>();
111:       // add entries for equals sorting
112:       for (int j = 0; j < i; j++) {
113:         final SearchColumn<?> sortColumn = sort.orderings().get(j).column();
114:         fieldEntries.add(
115:             new KeySetPaginationFieldEntry(sortColumn.name(), Operator.EQUALS, sortValues[j]));
116:       }
117: 
118:       // add comparator entry
119:       final var sorting = sort.orderings().get(i);
120:       fieldEntries.add(
121:           new KeySetPaginationFieldEntry(
122:               sorting.column().name(),
123:               determineOperator(sorting.order(), isSearchAfter),
124:               sortValues[i]));
125:       keySetPagination.add(new KeySetPagination(fieldEntries));
126:     }
127: 
128:     return keySetPagination;
129:   }
130: 
131:   protected final SearchQueryResult<T> buildSearchQueryResult(
132:       final long totalHits, final List<T> hits, final DbQuerySorting<T> dbSort) {
133:     final var result = new SearchQueryResult.Builder<T>().total(totalHits).items(hits);
134: 
135:     if (!hits.isEmpty()) {
136:       final var columns = dbSort.columns();
137:       result
138:           .searchBeforeCursor(Cursor.encode(hits.getFirst(), columns))
139:           .searchAfterCursor(Cursor.encode(hits.getLast(), columns));
140:     }
141: 
142:     return result.build();
143:   }
144: }
