91:                   .extracting(SearchResponse::items)
92:                   .asInstanceOf(InstanceOfAssertFactories.LIST)
93:                   .hasSameSizeAs(instanceKeys);
94: 
95:               // remove all completed instances
96:               response.get().items().stream()
97:                   .filter(inst -> inst.getState().equals(ProcessInstanceState.COMPLETED))
