121:                 camundaClient
122:                     .newCompleteCommand(job.getKey())
123:                     .variable(varName, job.getKey())
124:                     .send()
125:                     .join());
126:   }
127: 
128:   private void completeUserTasks() {
129:     LOGGER.debug("Starting to {} complete user tasks", instanceKeys.size());
