138:                             .newUserTaskSearchRequest()
139:                             .filter(f -> f.assignee(assignee).state(UserTaskState.CREATED))
140:                             .send()
141:                             .join()
142:                             .items();
143:                     LOGGER.debug("Found {} user tasks", itemsFromQuery.size());
144:                     return itemsFromQuery;
145:                   } catch (final RuntimeException e) {
146:                     LOGGER.warn("Failed to complete user tasks, will retry", e);
147:                     return List.of();
148:                   }
149:                 },
150:                 l -> l.size() == instanceKeys.size());
151:     LOGGER.debug("Fetched {} user tasks", items.size());
152: 
153:     items.forEach(
154:         item -> {
155:           LOGGER.debug("Completing user task {}", item.getUserTaskKey());
156:           assertThat(
157:                   camundaClient
158:                       .newUserTaskCompleteCommand(item.getUserTaskKey())
159:                       .send()
160:                       .toCompletableFuture())
161:               .succeedsWithin(timeout);
162:         });
163:   }
