170:   class OneTaskProcess {
171: 
172:     final String bpmnProcessId;
173: 
174:     private final String[] tasks = {"task1", "userTask"};
175: 
176:     OneTaskProcess(final String bpmnProcessId) {
177:       this.bpmnProcessId = bpmnProcessId;
178:     }
179: 
180:     private BpmnModelInstance createModel() {
181:       return Bpmn.createExecutableProcess(bpmnProcessId)
182:           .startEvent("start")
183:           .serviceTask(tasks[0])
184:           .zeebeJobType(tasks[0])
185:           .zeebeInput("=var1", "varIn")
186:           .userTask(tasks[1])
187:           .zeebeUserTask()
188:           .zeebeInput("=var3", "varIn")
189:           .zeebeAssignee(assignee)
190:           .endEvent()
191:           .done();
192:     }
193: 
194:     private void startProcessInstance(final Object payload) {
195:       final var evt =
196:           camundaClient
197:               .newCreateInstanceCommand()
198:               .bpmnProcessId(bpmnProcessId)
199:               .latestVersion()
200:               .variables(Map.of("var1", payload))
201:               .send()
202:               .join();
203:       LOGGER.debug("Process instance started with key {}", evt.getProcessInstanceKey());
204:       instanceKeys.add(evt.getProcessInstanceKey());
205:     }
