255:       final var query =
256:           SearchQueryBuilders.processInstanceSearchQuery()
257:               .filter(filter)
258:               .page(page)
259:               .resultConfig(c -> c.onlyKey(true))
260:               .build();
261: 
262:       final SearchQueryResult<ProcessInstanceEntity> result =
263:           searchClientsProxy.withSecurityContext(securityContext).searchProcessInstances(query);
264: 
265:       return new ItemPage(
266:           result.items().stream()
267:               .map(pi -> new Item(pi.processInstanceKey(), pi.processInstanceKey()))
268:               .collect(Collectors.toList()),
269:           result.lastSortValues(),
270:           result.total());
271:     }
272:   }
