530: 
531:     assertThat(result.items().size()).isEqualTo(8);
532: 
533:     // Assert that the creation date of item 0 is before item 1, and item 1 is before item 2
534:     final UserTask firstItem = result.items().get(0);
535:     final UserTask lastItem = result.items().get(7);
536:     assertThat(firstItem.getCreationDate()).isLessThan(result.items().get(1).getCreationDate());
537:     assertThat(result.items().get(1).getCreationDate())
538:         .isLessThan(result.items().get(2).getCreationDate());
539: 
540:     // Assert First and Last Sort Value matches the first and last item
541:     // We need to make use of toString, such the test work with ES/OS
542:     final List<String> firstSortValues =
543:         result.page().searchBeforeCursor().stream().map(Object::toString).toList();
544:     String creationDateMillis = convertDateIfNeeded(firstSortValues.getFirst());
545:     String userTaskKey = firstSortValues.getLast();
546: 
547:     assertThat(creationDateMillis)
548:         .isEqualTo(
549:             Long.toString(
550:                 OffsetDateTime.parse(firstItem.getCreationDate()).toInstant().toEpochMilli()));
551:     assertThat(userTaskKey).isEqualTo(Long.toString(firstItem.getUserTaskKey()));
552: 
553:     final List<String> lastSortValues =
554:         result.page().lastSortValues().stream().map(Object::toString).toList();
555:     creationDateMillis = convertDateIfNeeded(lastSortValues.getFirst());
556:     userTaskKey = lastSortValues.getLast();
557: 
558:     assertThat(creationDateMillis)
559:         .isEqualTo(
560:             Long.toString(
561:                 OffsetDateTime.parse(lastItem.getCreationDate()).toInstant().toEpochMilli()));
562:     assertThat(userTaskKey).isEqualTo(Long.toString(lastItem.getUserTaskKey()));
563:   }
