220:    * @param batchOperationKey the key of the batch operation
221:    * @param batchOperationType the type of batch operation
222:    * @return the created or existing ResourceSample for the latency
223:    */
224:   private ResourceSample createLatency(
225:       final BatchOperationLatency latencyType,
226:       final Long batchOperationKey,
227:       final BatchOperationType batchOperationType) {
228:     return latency.computeIfAbsent(
229:         createLatencyKey(latencyType, batchOperationKey),
230:         (key) -> registerBatchOperationLatency(batchOperationKey, latencyType, batchOperationType));
231:   }
232: 
233:   /**
234:    * Closes the latency measurement and removes it from the map. If the latency measurement does not
235:    * exist, it does nothing.
236:    *
237:    * @param latency the latency type to close
238:    * @param batchOperationKey the key of the batch operation
239:    */
240:   private void closeAndRemoveLatency(
241:       final BatchOperationLatency latency, final Long batchOperationKey) {
242:     final var key = createLatencyKey(latency, batchOperationKey);
243:     if (this.latency.containsKey(key)) {
244:       this.latency.get(key).close();
245:       this.latency.remove(key);
246:     }
247:   }
248: 
249:   private static Tuple<BatchOperationLatency, Long> createLatencyKey(
250:       final BatchOperationLatency latency, final Long batchOperationKey) {
251:     return Tuple.of(latency, batchOperationKey);
252:   }
253: 
254:   private ResourceSample registerBatchOperationLatency(
255:       final Long batchOperationKey,
256:       final BatchOperationLatency batchOperationLatency,
257:       final BatchOperationType batchOperationType) {
258:     final var meterDoc = BatchOperationMetricsDoc.BATCH_OPERATION_LATENCY;
259:     return Timer.resource(registry, meterDoc.getName())
260:         .description(meterDoc.getDescription())
261:         .tag(
262:             BatchOperationKeyNames.BATCH_OPERATION_KEY.asString(),
263:             String.valueOf(batchOperationKey))
264:         .tag(PartitionKeyNames.PARTITION.asString(), String.valueOf(partitionId))
265:         .tag(BatchOperationKeyNames.LATENCY.asString(), batchOperationLatency.toString())
266:         .tag(BatchOperationKeyNames.BATCH_OPERATION_TYPE.asString(), batchOperationType.toString())
267:         .tag(BatchOperationKeyNames.ORGANIZATION_ID.asString(), ORGANIZATION_ID);
268:   }
